-- Isolated question set and narrowly scoped Error Identifier administrator.
create table public.error_identifier_jayden_key(number integer primary key check(number between 1 and 300), data jsonb not null);
create table public.error_identifier_jayden_progress(student_id uuid references public.flashcard_students(id) on delete cascade, number integer references public.error_identifier_jayden_key(number), answer jsonb not null, updated_at timestamptz not null default now(), primary key(student_id,number));
create table public.error_identifier_admin_accounts(id uuid primary key default gen_random_uuid(), name text unique not null, password_hash text not null);
create table public.error_identifier_admin_sessions(token uuid primary key default gen_random_uuid(), admin_id uuid not null references public.error_identifier_admin_accounts(id), auth_id uuid not null, expires_at timestamptz not null default now()+interval '4 hours');
create table public.error_identifier_admin_attempts(name text primary key, attempts integer not null default 0, since timestamptz not null default now());
alter table public.error_identifier_jayden_key enable row level security;
alter table public.error_identifier_jayden_progress enable row level security;
alter table public.error_identifier_admin_accounts enable row level security;
alter table public.error_identifier_admin_sessions enable row level security;
alter table public.error_identifier_admin_attempts enable row level security;
revoke all on public.error_identifier_jayden_key,public.error_identifier_jayden_progress,public.error_identifier_admin_accounts,public.error_identifier_admin_sessions,public.error_identifier_admin_attempts from public,anon,authenticated;
create function public.error_identifier_admin_login(p_name text,p_password text) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.error_identifier_admin_accounts; t uuid; n integer;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_name is null or p_password is null or length(p_name)>100 or length(p_password)>200 then return jsonb_build_object('error','登入資料不正確。'); end if;
 if n>10 then return jsonb_build_object('error','嘗試次數過多，請 15 分鐘後再試。'); end if;
 select * into a from public.error_identifier_admin_accounts where lower(name)=lower(trim(p_name));
 if a.id is null or a.password_hash is distinct from extensions.crypt(p_password,a.password_hash) then return jsonb_build_object('error','登入資料不正確。'); end if;
 delete from public.error_identifier_admin_attempts where name=lower(trim(p_name));
 delete from public.error_identifier_admin_sessions where expires_at<now();
 return jsonb_build_object('token',t,'name',a.name);
end $$;
create function public.error_identifier_admin_answers(p_token uuid,p_logout boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not exists(select 1 from public.error_identifier_admin_sessions where token=p_token and auth_id=auth.uid() and expires_at>now()) then raise exception 'Admin session expired' using errcode='42501'; end if;
 if p_logout then delete from public.error_identifier_admin_sessions where token=p_token; return '{}'::jsonb; end if;
 return jsonb_build_object('single',(select jsonb_agg(to_jsonb(k) order by question_no) from public.error_identifier_answer_key k),'passages',(select jsonb_agg(to_jsonb(k) order by passage_id,line_no) from public.error_identifier_passage_answer_key k),'jayden',(select jsonb_agg(data order by number) from public.error_identifier_jayden_key));
end $$;
create function public.error_identifier_jayden_action(p_token uuid,p_number integer default null,p_answer jsonb default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare sid uuid; result jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 sid:=public.flashcard_session_student_id(p_token);
 if sid is null then raise exception 'Student session expired' using errcode='42501'; end if;
 if p_answer is not null then
  if p_number is null or p_number not between 1 and 300 or jsonb_typeof(p_answer)<>'object' or pg_column_size(p_answer)>4000 or coalesce(p_answer->>'mark','') not in ('tick','cross') then raise exception 'Invalid answer'; end if;
  if p_answer->>'mark'='cross' and (length(trim(coalesce(p_answer->>'wrong','')))=0 or length(trim(coalesce(p_answer->>'fix','')))=0) then raise exception 'Complete the correction'; end if;
 end if;
 select jsonb_build_object('answers',coalesce(jsonb_object_agg(p.number::text,p.answer),'{}'::jsonb),'feedback',coalesce(jsonb_object_agg(p.number::text,k.data),'{}'::jsonb)) into result from public.error_identifier_jayden_progress p join public.error_identifier_jayden_key k using(number) where student_id=sid;
 return result;
end $$;
revoke all on function public.error_identifier_admin_login(text,text),public.error_identifier_admin_answers(uuid,boolean),public.error_identifier_jayden_action(uuid,integer,jsonb) from public,anon;
grant execute on function public.error_identifier_admin_login(text,text),public.error_identifier_admin_answers(uuid,boolean),public.error_identifier_jayden_action(uuid,integer,jsonb) to authenticated;
-- Keep privileged implementations outside the exposed API schema.
create schema if not exists error_identifier_private;
revoke all on schema error_identifier_private from public,anon;
grant usage on schema error_identifier_private to authenticated;
alter function public.error_identifier_admin_login(text,text) set schema error_identifier_private;
alter function public.error_identifier_admin_answers(uuid,boolean) set schema error_identifier_private;
alter function public.error_identifier_jayden_action(uuid,integer,jsonb) set schema error_identifier_private;
create function public.error_identifier_admin_login(p_name text,p_password text) returns jsonb language sql security invoker set search_path='' as $$ select error_identifier_private.error_identifier_admin_login(p_name,p_password) $$;
create function public.error_identifier_admin_answers(p_token uuid,p_logout boolean default false) returns jsonb language sql security invoker set search_path='' as $$ select error_identifier_private.error_identifier_admin_answers(p_token,p_logout) $$;
create function public.error_identifier_jayden_action(p_token uuid,p_number integer default null,p_answer jsonb default null) returns jsonb language sql security invoker set search_path='' as $$ select error_identifier_private.error_identifier_jayden_action(p_token,p_number,p_answer) $$;
revoke all on function public.error_identifier_admin_login(text,text),public.error_identifier_admin_answers(uuid,boolean),public.error_identifier_jayden_action(uuid,integer,jsonb) from public,anon;
grant execute on function public.error_identifier_admin_login(text,text),public.error_identifier_admin_answers(uuid,boolean),public.error_identifier_jayden_action(uuid,integer,jsonb) to authenticated;
