 insert into public.error_identifier_admin_attempts(name,attempts) values(lower(trim(p_name)),1) on conflict(name) do update set attempts=case when error_identifier_admin_attempts.since<now()-interval '15 minutes' then 1 else error_identifier_admin_attempts.attempts+1 end,since=case when error_identifier_admin_attempts.since<now()-interval '15 minutes' then now() else error_identifier_admin_attempts.since end returning attempts into n;
 insert into public.error_identifier_admin_sessions(admin_id,auth_id) values(a.id,auth.uid()) returning token into t;
  insert into public.error_identifier_jayden_progress(student_id,number,answer) values(sid,p_number,p_answer) on conflict(student_id,number) do update set answer=excluded.answer,updated_at=now();
insert into public.error_identifier_jayden_key(number,data) values (1,'{"number": 1, "sentence": "The student does not has to rewrite the entire essay.", "mark": "cross", "topic": "does not have to + 原形", "wrong": "does not has to", "fix": "does not have to", "correct_sentence": "The student does not have to rewrite the entire essay.", "hint": "主語是 he/she/it，而句子要說「不必」。", "location": "把原句的「does not has to」圈起來，與同一位置應有的「does not have to」比較。不要把沒有錯的部分一併重寫。", "reason": "does not have to + 原形；前面有 does 時，不能說 doesn’t has to。", "tip": "does 已經負責第三身單數，have 不再變 has。", "course": "E Must / have to / need to；細項 45。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (2,'{"number": 2, "sentence": "The pupils bringed food to the elderly centre yesterday.", "mark": "cross", "topic": "不規則過去式", "wrong": "bringed", "fix": "brought", "correct_sentence": "The pupils brought food to the elderly centre yesterday.", "hint": "句子已有明確過去時間；找動詞的過去式是否拼對。", "location": "把原句的「bringed」圈起來，與同一位置應有的「brought」比較。不要把沒有錯的部分一併重寫。", "reason": "有些動詞不直接加 -ed，例如 strike → struck、go → went、bring → brought。", "tip": "常錯的動詞三態要逐個背，不能一律加 -ed。", "course": "G 前置知識與 if 條件句；細項 60。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (3,'{"number": 3, "sentence": "Every participant must to wear a name badge.", "mark": "cross", "topic": "must 後接動詞原形", "wrong": "must to wear", "fix": "must wear", "correct_sentence": "Every participant must wear a name badge.", "hint": "找到 must，再看緊接的動詞。", "location": "把原句的「must to wear」圈起來，與同一位置應有的「must wear」比較。不要把沒有錯的部分一併重寫。", "reason": "must 後必須用動詞原形，不能接 to 或過去式；例如 must finish。", "tip": "must 後面的動詞不要加 -s、-ed 或 to。", "course": "B 不帶 to 的動詞原形；細項 17。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (4,'{"number": 4, "sentence": "The students were rehearsing when the alarm rang.", "mark": "tick", "topic": "過去進行式：背景 + 突發事件", "wrong": "", "fix": "", "correct_sentence": "The students were rehearsing when the alarm rang.", "hint": "一件事發生時，另一件事情正在進行。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "長一點的背景動作用 was/were + -ing；較短的插入事件用一般過去式。", "tip": "一條時間線：was reading → phone rang。", "course": "G 前置知識與 if 條件句；細項 61。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (5,'{"number": 5, "sentence": "The boy is runing around the playground.", "mark": "cross", "topic": "-ing 的拼字變化", "wrong": "runing", "fix": "running", "correct_sentence": "The boy is running around the playground.", "hint": "已確定要用進行式，再檢查動詞的 -ing 拼字。", "location": "把原句的「runing」圈起來，與同一位置應有的「running」比較。不要把沒有錯的部分一併重寫。", "reason": "write → writing（去 e）；run → running（雙寫 n）；lie → lying（ie 變 y）。", "tip": "先選正確時態，再看字尾拼法。", "course": "A 現在式與現在進行式；細項 10。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (6,'{"number": 6, "sentence": "The coach explained the rules so as to the players understand them.", "mark": "cross", "topic": "so as to 的動作主語要一致", "wrong": "so as to the players understand", "fix": "so that the players could understand", "correct_sentence": "The coach explained the rules so that the players could understand them.", "hint": "比較主句誰做動作，以及 so as to 後誰想達到目的。", "location": "把原句的「so as to the players understand」圈起來，與同一位置應有的「so that the players could understand」比較。不要把沒有錯的部分一併重寫。", "reason": "so as to 的未明說主語通常就是主句主語；若目的是讓另一個人做事，改用 so that + 那個人 + can/could。", "tip": "問兩次「是誰做？」；不同人便考慮 so that。", "course": "F So / so that / so as to；細項 58。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (7,'{"number": 7, "sentence": "The bus leave at seven every morning.", "mark": "cross", "topic": "現在習慣：頻率副詞", "wrong": "leave", "fix": "leaves", "correct_sentence": "The bus leaves at seven every morning.", "hint": "留意 usually、often、every morning 等字；它們在說日常習慣。", "location": "把原句的「leave」圈起來，與同一位置應有的「leaves」比較。不要把沒有錯的部分一併重寫。", "reason": "習慣是反覆發生的事，通常用一般現在式，不用過去式或為了「正在」而硬加 -ing。", "tip": "看到頻率字，先問「是天天如此，還是此刻一次？」", "course": "A 現在式與現在進行式；細項 01。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (8,'{"number": 8, "sentence": "She is sometimes late for rehearsal.", "mark": "tick", "topic": "現在式的 always / never / sometimes", "wrong": "", "fix": "", "correct_sentence": "She is sometimes late for rehearsal.", "hint": "留意 always、never、sometimes 放在主要動詞附近。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "頻率副詞通常放在一般動詞前、be 動詞後；「never」本身已表示否定。", "tip": "問自己：是否把 never 再配 not，變成雙重否定？", "course": "A 現在式與現在進行式；細項 07。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (9,'{"number": 9, "sentence": "Students may use the computers after lunch.", "mark": "tick", "topic": "should / may / might 後原形", "wrong": "", "fix": "", "correct_sentence": "Students may use the computers after lunch.", "hint": "找到 should、may 或 might；它們都屬情態動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "should/may/might 後面直接接原形，不要多加 to 或 -ing。", "tip": "試用 should go、may leave、might rain 記憶。", "course": "B 不帶 to 的動詞原形；細項 18。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (10,'{"number": 10, "sentence": "I set an alarm so as to arrive on time.", "mark": "tick", "topic": "so as to + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "I set an alarm so as to arrive on time.", "hint": "看 so as to 後面的動詞形式。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "so as to 後直接接原形，表示「為了」：so as to save time。", "tip": "so as to finish，不是 so as to finishing。", "course": "F So / so that / so as to；細項 56。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (11,'{"number": 11, "sentence": "Water freezes at zero degrees Celsius.", "mark": "tick", "topic": "一般事實及科學真理", "wrong": "", "fix": "", "correct_sentence": "Water freezes at zero degrees Celsius.", "hint": "句子在講普遍成立的事實，而不是某個人此刻正在做的事。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "科學事實、定義、自然規律常用一般現在式；沒有理由就不要改成現在進行式。", "tip": "先想：「這句話明天也通常成立嗎？」成立就傾向用現在式。", "course": "A 現在式與現在進行式；細項 02。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (12,'{"number": 12, "sentence": "They have been waiting since forty minutes.", "mark": "cross", "topic": "for / since 的時間用法", "wrong": "since forty minutes", "fix": "for forty minutes", "correct_sentence": "They have been waiting for forty minutes.", "hint": "找出時間是「一段長度」還是「開始那個點」。", "location": "把原句的「since forty minutes」圈起來，與同一位置應有的「for forty minutes」比較。不要把沒有錯的部分一併重寫。", "reason": "for + 一段時間（for three years）；since + 起點（since 2023）。", "tip": "for = 多久；since = 從何時開始。", "course": "G 前置知識與 if 條件句；細項 64。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (13,'{"number": 13, "sentence": "They completed five experiments up to now.", "mark": "cross", "topic": "現在完成式：至今的成果", "wrong": "completed", "fix": "have completed", "correct_sentence": "They have completed five experiments up to now.", "hint": "留意 so far、up to now、since 等與現在仍有關係的時間線索。", "location": "把原句的「completed」圈起來，與同一位置應有的「have completed」比較。不要把沒有錯的部分一併重寫。", "reason": "have/has + 過去分詞，說明以前發生而與現在有關的結果。", "tip": "「至今」想 have/has done；「昨天」想 did。", "course": "G 前置知識與 if 條件句；細項 63。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (14,'{"number": 14, "sentence": "My friend waiting outside the hall.", "mark": "cross", "topic": "進行式：am/is/are + -ing", "wrong": "waiting", "fix": "is waiting", "correct_sentence": "My friend is waiting outside the hall.", "hint": "留意 right now、at the moment；找主語、be 和 -ing 是否齊全。", "location": "把原句的「waiting」圈起來，與同一位置應有的「is waiting」比較。不要把沒有錯的部分一併重寫。", "reason": "現在進行式有兩部分：am/is/are + 動詞-ing；不可只剩 -ing。", "tip": "三步檢查：「誰？」→「am/is/are？」→「-ing？」", "course": "A 現在式與現在進行式；細項 09。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (15,'{"number": 15, "sentence": "The funny video made everyone laugh.", "mark": "tick", "topic": "主動 make + 人 + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "The funny video made everyone laugh.", "hint": "句子的意思是「令某人做某事」，而 make 是主動式。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "make/made someone do something；主動使役用原形，不用 to do。", "tip": "made us clean；不要 made us to clean。", "course": "B 不帶 to 的動詞原形；細項 21。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (16,'{"number": 16, "sentence": "Do anybody know the answer to Question Five?", "mark": "cross", "topic": "問句的 anybody / anything", "wrong": "Do anybody", "fix": "Does anybody", "correct_sentence": "Does anybody know the answer to Question Five?", "hint": "普通問句在詢問是否有人／有東西，答案未知。", "location": "把原句的「Do anybody」圈起來，與同一位置應有的「Does anybody」比較。不要把沒有錯的部分一併重寫。", "reason": "一般中性問句多用 anyone/anybody/anything；但邀請或期待肯定回應的問句可以用 some-，不要一概硬改。", "tip": "先分清「中性查詢」還是「禮貌邀請」。", "course": "C 不定代名詞；細項 31。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (17,'{"number": 17, "sentence": "She does not listening to the announcement.", "mark": "cross", "topic": "進行式疑問句與否定句", "wrong": "does not listening", "fix": "is not listening", "correct_sentence": "She is not listening to the announcement.", "hint": "注意問句的 am/is/are 位置，以及否定句中的 not。", "location": "把原句的「does not listening」圈起來，與同一位置應有的「is not listening」比較。不要把沒有錯的部分一併重寫。", "reason": "問句把 be 放主語前：Are they coming?；否定用 is not / are not + -ing。", "tip": "把陳述句 They are waiting 改成問句 Are they waiting? 試一遍。", "course": "A 現在式與現在進行式；細項 11。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (18,'{"number": 18, "sentence": "You mustn’t share your login password with anyone.", "mark": "tick", "topic": "must not / mustn’t = 禁止", "wrong": "", "fix": "", "correct_sentence": "You mustn’t share your login password with anyone.", "hint": "告示清楚說不准做一件事。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "must not 表「不准」，不是「沒有必要」；必要時與 do not have to 作比較。", "tip": "看到 No entry / strictly prohibited，想 must not。", "course": "E Must / have to / need to；細項 42。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (19,'{"number": 19, "sentence": "Did anybody leave a blue umbrella here?", "mark": "tick", "topic": "問句的 anybody / anything", "wrong": "", "fix": "", "correct_sentence": "Did anybody leave a blue umbrella here?", "hint": "普通問句在詢問是否有人／有東西，答案未知。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般中性問句多用 anyone/anybody/anything；但邀請或期待肯定回應的問句可以用 some-，不要一概硬改。", "tip": "先分清「中性查詢」還是「禮貌邀請」。", "course": "C 不定代名詞；細項 31。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (20,'{"number": 20, "sentence": "Unless the bus will arrive soon, we will take the MTR.", "mark": "cross", "topic": "unless 後談將來常用現在式", "wrong": "bus will arrive", "fix": "bus arrives", "correct_sentence": "Unless the bus arrives soon, we will take the MTR.", "hint": "前面 unless 子句是在講將來可能出現的條件。", "location": "把原句的「bus will arrive」圈起來，與同一位置應有的「bus arrives」比較。不要把沒有錯的部分一併重寫。", "reason": "一般未來條件句中，unless 後通常用現在式；結果部分才用 will + 原形。", "tip": "Unless it rains, we will go；不要 Unless it will rain。", "course": "D Unless 條件句；細項 36。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (21,'{"number": 21, "sentence": "You had better save your work before closing the file.", "mark": "tick", "topic": "had better + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "You had better save your work before closing the file.", "hint": "留意 had better 這一組提出建議的字。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "had better 後直接接原形：had better leave；雖有 had，不表示動詞要用過去式。", "tip": "had better 不加 to。", "course": "B 不帶 to 的動詞原形；細項 22。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (22,'{"number": 22, "sentence": "Our class is visiting the museum next Tuesday.", "mark": "tick", "topic": "已安排的將來：現在進行式", "wrong": "", "fix": "", "correct_sentence": "Our class is visiting the museum next Tuesday.", "hint": "留意 tomorrow 或 next week，並且有已約好、已預訂的安排。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "現在進行式亦可說明已安排好的將來約會：We are meeting at four。", "tip": "「已約好」與「只是猜想」不一樣。", "course": "A 現在式與現在進行式；細項 14。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (23,'{"number": 23, "sentence": "We need to discuss the budget with our teacher.", "mark": "tick", "topic": "need to + 原形", "wrong": "", "fix": "", "correct_sentence": "We need to discuss the budget with our teacher.", "hint": "句子在說有一件需要完成的事情。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般動詞 need 接 to-infinitive：need to finish；不要接 need finish（這裡不是情態用法）。", "tip": "I need to + 動詞原形。", "course": "E Must / have to / need to；細項 46。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (24,'{"number": 24, "sentence": "Nobody knows the password except the librarian.", "mark": "tick", "topic": "nobody / no one + 單數動詞", "wrong": "", "fix": "", "correct_sentence": "Nobody knows the password except the librarian.", "hint": "句子主語是 nobody / no one。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "nobody/no one 雖然表示沒有人，仍用單數動詞：Nobody knows。", "tip": "不要見到「沒有人」就誤用複數動詞。", "course": "C 不定代名詞；細項 28。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (25,'{"number": 25, "sentence": "Our teacher suggested taking a short break.", "mark": "tick", "topic": "enjoy / avoid / suggest 後用 -ing", "wrong": "", "fix": "", "correct_sentence": "Our teacher suggested taking a short break.", "hint": "找到 enjoy、avoid、suggest，檢查下一個動詞形式。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "這類動詞常接動名詞：enjoy reading、avoid making、suggest working。", "tip": "見到三個動詞，先試用 -ing，不要直接加 to。", "course": "G 前置知識與 if 條件句；細項 68。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (26,'{"number": 26, "sentence": "The team needn’t bringing any extra chairs.", "mark": "cross", "topic": "needn’t 後直接原形", "wrong": "needn’t bringing", "fix": "needn’t bring", "correct_sentence": "The team needn’t bring any extra chairs.", "hint": "這是情態用法 needn’t，與 don’t need to 結構不同。", "location": "把原句的「needn’t bringing」圈起來，與同一位置應有的「needn’t bring」比較。不要把沒有錯的部分一併重寫。", "reason": "needn’t + 原形，不加 to；例 needn’t worry。", "tip": "分清 needn’t go 與 don’t need to go。", "course": "E Must / have to / need to；細項 48。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (27,'{"number": 27, "sentence": "I having lunch with the debate coach tomorrow; we have reserved a table.", "mark": "cross", "topic": "已安排的將來：現在進行式", "wrong": "having", "fix": "am having", "correct_sentence": "I am having lunch with the debate coach tomorrow; we have reserved a table.", "hint": "留意 tomorrow 或 next week，並且有已約好、已預訂的安排。", "location": "把原句的「having」圈起來，與同一位置應有的「am having」比較。不要把沒有錯的部分一併重寫。", "reason": "現在進行式亦可說明已安排好的將來約會：We are meeting at four。", "tip": "「已約好」與「只是猜想」不一樣。", "course": "A 現在式與現在進行式；細項 14。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (28,'{"number": 28, "sentence": "Everything is ready for the prize ceremony.", "mark": "tick", "topic": "everything / something 單數一致", "wrong": "", "fix": "", "correct_sentence": "Everything is ready for the prize ceremony.", "hint": "everything、something 指事物，但當作單數。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "Everything is ready，Something looks strange；不能用 are 或 look（原形）配單數主語。", "tip": "以 it 代替 everything 試試動詞。", "course": "C 不定代名詞；細項 29。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (29,'{"number": 29, "sentence": "The young pianist could played the piece by heart.", "mark": "cross", "topic": "can / could 後接動詞原形", "wrong": "could played", "fix": "could play", "correct_sentence": "The young pianist could play the piece by heart.", "hint": "找到 can 或 could，看看後面的動詞有沒有多加 to、-s 或 -ing。", "location": "把原句的「could played」圈起來，與同一位置應有的「could play」比較。不要把沒有錯的部分一併重寫。", "reason": "can/could 是情態動詞，後面直接跟原形：can swim，不是 can to swim。", "tip": "把 can、could 與下一個動詞連在一起檢查。", "course": "B 不帶 to 的動詞原形；細項 16。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (30,'{"number": 30, "sentence": "The baby is lying quietly on the sofa.", "mark": "tick", "topic": "-ing 的拼字變化", "wrong": "", "fix": "", "correct_sentence": "The baby is lying quietly on the sofa.", "hint": "已確定要用進行式，再檢查動詞的 -ing 拼字。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "write → writing（去 e）；run → running（雙寫 n）；lie → lying（ie 變 y）。", "tip": "先選正確時態，再看字尾拼法。", "course": "A 現在式與現在進行式；細項 10。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (31,'{"number": 31, "sentence": "It might raining during the outdoor concert.", "mark": "cross", "topic": "should / may / might 後原形", "wrong": "might raining", "fix": "might rain", "correct_sentence": "It might rain during the outdoor concert.", "hint": "找到 should、may 或 might；它們都屬情態動詞。", "location": "把原句的「might raining」圈起來，與同一位置應有的「might rain」比較。不要把沒有錯的部分一併重寫。", "reason": "should/may/might 後面直接接原形，不要多加 to 或 -ing。", "tip": "試用 should go、may leave、might rain 記憶。", "course": "B 不帶 to 的動詞原形；細項 18。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (32,'{"number": 32, "sentence": "We need someone to carry the heavy boxes.", "mark": "tick", "topic": "人用 -one/-body；物用 -thing", "wrong": "", "fix": "", "correct_sentence": "We need someone to carry the heavy boxes.", "hint": "留意動詞的意思：是否在找人，還是在找東西？", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "someone/anyone/nobody 說人；something/anything/nothing 說事物。", "tip": "直接問「要找的是人還是物？」", "course": "C 不定代名詞；細項 33。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (33,'{"number": 33, "sentence": "They using a temporary classroom this term.", "mark": "cross", "topic": "短期情況與長期習慣", "wrong": "using", "fix": "are using", "correct_sentence": "They are using a temporary classroom this term.", "hint": "留意 this week、this month、for now 和 usually 的對比。", "location": "把原句的「using」圈起來，與同一位置應有的「are using」比較。不要把沒有錯的部分一併重寫。", "reason": "平常習慣用現在式；只在這段時間暫時發生的事情常用進行式。", "tip": "把「通常」和「暫時」在心中分開。", "course": "A 現在式與現在進行式；細項 12。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (34,'{"number": 34, "sentence": "I was doing my homework when the lights went out.", "mark": "tick", "topic": "過去進行式：背景 + 突發事件", "wrong": "", "fix": "", "correct_sentence": "I was doing my homework when the lights went out.", "hint": "一件事發生時，另一件事情正在進行。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "長一點的背景動作用 was/were + -ing；較短的插入事件用一般過去式。", "tip": "一條時間線：was reading → phone rang。", "course": "G 前置知識與 if 條件句；細項 61。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (35,'{"number": 35, "sentence": "The team must submits its design by Friday.", "mark": "cross", "topic": "must 後接動詞原形", "wrong": "must submits", "fix": "must submit", "correct_sentence": "The team must submit its design by Friday.", "hint": "找到 must，再看緊接的動詞。", "location": "把原句的「must submits」圈起來，與同一位置應有的「must submit」比較。不要把沒有錯的部分一併重寫。", "reason": "must 後必須用動詞原形，不能接 to 或過去式；例如 must finish。", "tip": "must 後面的動詞不要加 -s、-ed 或 to。", "course": "B 不帶 to 的動詞原形；細項 17。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (36,'{"number": 36, "sentence": "He has finished his homework an hour ago.", "mark": "cross", "topic": "一般過去式：已完結的時間", "wrong": "has finished", "fix": "finished", "correct_sentence": "He finished his homework an hour ago.", "hint": "留意 yesterday、last week、two days ago，事情已經結束。", "location": "把原句的「has finished」圈起來，與同一位置應有的「finished」比較。不要把沒有錯的部分一併重寫。", "reason": "特定過去時間發生的事件通常用一般過去式；不要混用現在完成式。", "tip": "看到 ago，先想到 did，而不是 have done。", "course": "G 前置知識與 if 條件句；細項 59。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (37,'{"number": 37, "sentence": "The lights went out, so the audience waited quietly.", "mark": "tick", "topic": "so 表結果，不是 so to + 動詞", "wrong": "", "fix": "", "correct_sentence": "The lights went out, so the audience waited quietly.", "hint": "看看 so 後是不是直接跟着 to + 動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "so 通常連接結果子句；表示目的要用 so as to + 原形，不能隨意寫 so to。", "tip": "so + 完整句；so as to + 原形。", "course": "F So / so that / so as to；細項 52。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (38,'{"number": 38, "sentence": "The team had to practise indoors because of the storm.", "mark": "tick", "topic": "過去的必須：had to", "wrong": "", "fix": "", "correct_sentence": "The team had to practise indoors because of the storm.", "hint": "事情是昨天、去年或上星期發生的強制要求。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "普通義務要談過去，常用 had to；must 不能當作一般動詞變 musted。", "tip": "現在 have to；過去 had to。", "course": "E Must / have to / need to；細項 49。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (39,'{"number": 39, "sentence": "Everybody have a part to play in the performance.", "mark": "cross", "topic": "everyone / everybody 用單數動詞", "wrong": "have", "fix": "has", "correct_sentence": "Everybody has a part to play in the performance.", "hint": "留意 everyone、everybody 雖然指很多人，文法上當單數。", "location": "把原句的「have」圈起來，與同一位置應有的「has」比較。不要把沒有錯的部分一併重寫。", "reason": "everyone/everybody + is/has/動詞-s；不能因為意思是「所有人」而用 are。", "tip": "把 everyone 當作 he/she 來試配動詞。", "course": "C 不定代名詞；細項 26。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (40,'{"number": 40, "sentence": "Every visitor must to follow the safety instructions.", "mark": "cross", "topic": "must + 動詞原形", "wrong": "must to follow", "fix": "must follow", "correct_sentence": "Every visitor must follow the safety instructions.", "hint": "must 表示強烈的責任、要求或必要。", "location": "把原句的「must to follow」圈起來，與同一位置應有的「must follow」比較。不要把沒有錯的部分一併重寫。", "reason": "must + 原形；不接 to，不因主語單數而變 musts。", "tip": "must 的下一個動詞保持原形。", "course": "E Must / have to / need to；細項 41。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (41,'{"number": 41, "sentence": "The box of old photographs belong to the library.", "mark": "cross", "topic": "現在式主謂一致：近距離陷阱", "wrong": "belong", "fix": "belongs", "correct_sentence": "The box of old photographs belongs to the library.", "hint": "找真正主語，不要被中間的 of、with、along with 或長修飾語騙到。", "location": "把原句的「belong」圈起來，與同一位置應有的「belongs」比較。不要把沒有錯的部分一併重寫。", "reason": "the number of students 是單數主語 number；the students 是複數；動詞要跟真正主語配合。", "tip": "先遮住主語後面那一長串修飾語。", "course": "G 前置知識與 if 條件句；細項 74。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (42,'{"number": 42, "sentence": "We heard the school bell to ring twice.", "mark": "cross", "topic": "感官動詞 see / hear + 人 + 原形", "wrong": "heard the school bell to ring", "fix": "heard the school bell ring", "correct_sentence": "We heard the school bell ring twice.", "hint": "找 see、saw、hear、heard 後是否接了人，再接動詞。", "location": "把原句的「heard the school bell to ring」圈起來，與同一位置應有的「heard the school bell ring」比較。不要把沒有錯的部分一併重寫。", "reason": "描述看見／聽見整個動作，可以用 saw him cross；不能用 saw him to cross。另有 -ing 用法，但意思不同，不能把它當錯。", "tip": "感官動詞 + 人 + 原形；別在中間硬加 to。", "course": "B 不帶 to 的動詞原形；細項 24。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (43,'{"number": 43, "sentence": "Unless you wear a helmet, you cannot enter the cycling track.", "mark": "tick", "topic": "unless 的邏輯：不要誤加 not", "wrong": "", "fix": "", "correct_sentence": "Unless you wear a helmet, you cannot enter the cycling track.", "hint": "看 unless 後面的否定字會不會把原意倒轉。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "unless 已含「如果不」；若再加 not，整句條件會變成另一種意思，不是每次都錯，必須用上下文判斷。", "tip": "先把 unless 改寫成 if not，再檢查有沒有兩個「不」。", "course": "D Unless 條件句；細項 37。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (44,'{"number": 44, "sentence": "Unless you will study tonight, you will find the quiz difficult.", "mark": "cross", "topic": "unless 後談將來常用現在式", "wrong": "you will study", "fix": "you study", "correct_sentence": "Unless you study tonight, you will find the quiz difficult.", "hint": "前面 unless 子句是在講將來可能出現的條件。", "location": "把原句的「you will study」圈起來，與同一位置應有的「you study」比較。不要把沒有錯的部分一併重寫。", "reason": "一般未來條件句中，unless 後通常用現在式；結果部分才用 will + 原形。", "tip": "Unless it rains, we will go；不要 Unless it will rain。", "course": "D Unless 條件句；細項 36。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (45,'{"number": 45, "sentence": "She saw her friend to pick up the lost wallet.", "mark": "cross", "topic": "感官動詞 see / hear + 人 + 原形", "wrong": "saw her friend to pick", "fix": "saw her friend pick", "correct_sentence": "She saw her friend pick up the lost wallet.", "hint": "找 see、saw、hear、heard 後是否接了人，再接動詞。", "location": "把原句的「saw her friend to pick」圈起來，與同一位置應有的「saw her friend pick」比較。不要把沒有錯的部分一併重寫。", "reason": "描述看見／聽見整個動作，可以用 saw him cross；不能用 saw him to cross。另有 -ing 用法，但意思不同，不能把它當錯。", "tip": "感官動詞 + 人 + 原形；別在中間硬加 to。", "course": "B 不帶 to 的動詞原形；細項 24。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (46,'{"number": 46, "sentence": "He doesn’t have to buy a new calculator.", "mark": "tick", "topic": "does not have to + 原形", "wrong": "", "fix": "", "correct_sentence": "He doesn’t have to buy a new calculator.", "hint": "主語是 he/she/it，而句子要說「不必」。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "does not have to + 原形；前面有 does 時，不能說 doesn’t has to。", "tip": "does 已經負責第三身單數，have 不再變 has。", "course": "E Must / have to / need to；細項 45。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (47,'{"number": 47, "sentence": "I look forward to receive your reply.", "mark": "cross", "topic": "介詞後用 -ing（動名詞）", "wrong": "to receive", "fix": "to receiving", "correct_sentence": "I look forward to receiving your reply.", "hint": "留意 look forward to、interested in、good at 等搭配。", "location": "把原句的「to receive」圈起來，與同一位置應有的「to receiving」比較。不要把沒有錯的部分一併重寫。", "reason": "介詞後接名詞或動名詞 -ing：interested in reading；其中 look forward to 的 to 是介詞。", "tip": "先判斷 to 是介詞還是不定式標誌。", "course": "G 前置知識與 if 條件句；細項 67。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (48,'{"number": 48, "sentence": "The pupils do not never forget their identity cards.", "mark": "cross", "topic": "現在式的 always / never / sometimes", "wrong": "do not never forget", "fix": "never forget", "correct_sentence": "The pupils never forget their identity cards.", "hint": "留意 always、never、sometimes 放在主要動詞附近。", "location": "把原句的「do not never forget」圈起來，與同一位置應有的「never forget」比較。不要把沒有錯的部分一併重寫。", "reason": "頻率副詞通常放在一般動詞前、be 動詞後；「never」本身已表示否定。", "tip": "問自己：是否把 never 再配 not，變成雙重否定？", "course": "A 現在式與現在進行式；細項 07。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (49,'{"number": 49, "sentence": "The club president has to prepare an annual report.", "mark": "tick", "topic": "he / she / it has to", "wrong": "", "fix": "", "correct_sentence": "The club president has to prepare an annual report.", "hint": "主語是單數，看看 have to 要不要變 has to。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "have to 不是情態動詞 must；一般現在式 he/she/it 要用 has to。", "tip": "he has to；they have to。", "course": "E Must / have to / need to；細項 43。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (50,'{"number": 50, "sentence": "Neither answers is correct, so we should check again.", "mark": "cross", "topic": "each / either / neither 的單數用法", "wrong": "Neither answers", "fix": "Neither answer", "correct_sentence": "Neither answer is correct, so we should check again.", "hint": "先找 each、either、neither，看看後面是否有單數名詞，或 of + 複數名詞。", "location": "把原句的「Neither answers」圈起來，與同一位置應有的「Neither answer」比較。不要把沒有錯的部分一併重寫。", "reason": "each/either/neither 指「每一個／兩者之一／兩者皆非」。直接接可數名詞時通常接單數：neither option；如果後接 of，則用 either of the two options。", "tip": "先判斷是否有 of；沒有 of 時通常是 each student / either route / neither answer。", "course": "C 不定代名詞；細項 39。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (51,'{"number": 51, "sentence": "She revised daily so to remember the vocabulary.", "mark": "cross", "topic": "so 表結果，不是 so to + 動詞", "wrong": "so to remember", "fix": "so as to remember", "correct_sentence": "She revised daily so as to remember the vocabulary.", "hint": "看看 so 後是不是直接跟着 to + 動詞。", "location": "把原句的「so to remember」圈起來，與同一位置應有的「so as to remember」比較。不要把沒有錯的部分一併重寫。", "reason": "so 通常連接結果子句；表示目的要用 so as to + 原形，不能隨意寫 so to。", "tip": "so + 完整句；so as to + 原形。", "course": "F So / so that / so as to；細項 52。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (52,'{"number": 52, "sentence": "I saw the runner cross the finish line.", "mark": "tick", "topic": "感官動詞 see / hear + 人 + 原形", "wrong": "", "fix": "", "correct_sentence": "I saw the runner cross the finish line.", "hint": "找 see、saw、hear、heard 後是否接了人，再接動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "描述看見／聽見整個動作，可以用 saw him cross；不能用 saw him to cross。另有 -ing 用法，但意思不同，不能把它當錯。", "tip": "感官動詞 + 人 + 原形；別在中間硬加 to。", "course": "B 不帶 to 的動詞原形；細項 24。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (53,'{"number": 53, "sentence": "The English lesson begins at nine next Monday.", "mark": "tick", "topic": "時間表：將來活動可用現在式", "wrong": "", "fix": "", "correct_sentence": "The English lesson begins at nine next Monday.", "hint": "句子談巴士、課堂、電影等固定時間表。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "已訂好的時間表即使在未來，也可以用一般現在式：The train leaves at six。", "tip": "看「固定時間表」而不只是看到 tomorrow 就改 will。", "course": "A 現在式與現在進行式；細項 08。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (54,'{"number": 54, "sentence": "The museum opens at ten tomorrow morning.", "mark": "tick", "topic": "時間表：將來活動可用現在式", "wrong": "", "fix": "", "correct_sentence": "The museum opens at ten tomorrow morning.", "hint": "句子談巴士、課堂、電影等固定時間表。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "已訂好的時間表即使在未來，也可以用一般現在式：The train leaves at six。", "tip": "看「固定時間表」而不只是看到 tomorrow 就改 will。", "course": "A 現在式與現在進行式；細項 08。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (55,'{"number": 55, "sentence": "She raised her hand so that teacher could notice her.", "mark": "cross", "topic": "so that 後有主語與動詞", "wrong": "so that teacher", "fix": "so that the teacher", "correct_sentence": "She raised her hand so that the teacher could notice her.", "hint": "so that 表示「為了讓……」，後面通常有完整的主語和謂語。", "location": "把原句的「so that teacher」圈起來，與同一位置應有的「so that the teacher」比較。不要把沒有錯的部分一併重寫。", "reason": "so that + 主語 + 動詞／情態動詞，不等於 so as to + 原形。", "tip": "檢查 so that 後，有沒有「誰做甚麼」。", "course": "F So / so that / so as to；細項 53。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (56,'{"number": 56, "sentence": "Our teacher let us to present the project first.", "mark": "cross", "topic": "let + 人 + 動詞原形", "wrong": "let us to present", "fix": "let us present", "correct_sentence": "Our teacher let us present the project first.", "hint": "找到 let，特別留意 let us / let me / let him 後面的動詞。", "location": "把原句的「let us to present」圈起來，與同一位置應有的「let us present」比較。不要把沒有錯的部分一併重寫。", "reason": "let someone do something，後面通常不用 to；例如 let me try。", "tip": "let + 人 + 原形，三件事排在一起。", "course": "B 不帶 to 的動詞原形；細項 20。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (57,'{"number": 57, "sentence": "We queued early so as to get good seats.", "mark": "tick", "topic": "so as to + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "We queued early so as to get good seats.", "hint": "看 so as to 後面的動詞形式。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "so as to 後直接接原形，表示「為了」：so as to save time。", "tip": "so as to finish，不是 so as to finishing。", "course": "F So / so that / so as to；細項 56。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (58,'{"number": 58, "sentence": "Everything depends on the weather tomorrow.", "mark": "tick", "topic": "everything / something 單數一致", "wrong": "", "fix": "", "correct_sentence": "Everything depends on the weather tomorrow.", "hint": "everything、something 指事物，但當作單數。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "Everything is ready，Something looks strange；不能用 are 或 look（原形）配單數主語。", "tip": "以 it 代替 everything 試試動詞。", "course": "C 不定代名詞；細項 29。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (59,'{"number": 59, "sentence": "The players were made repeated the drill.", "mark": "cross", "topic": "被動 be made + to + 動詞", "wrong": "made repeated", "fix": "made to repeat", "correct_sentence": "The players were made to repeat the drill.", "hint": "同樣是 make，但看誰是主語：是「被迫做」嗎？", "location": "把原句的「made repeated」圈起來，與同一位置應有的「made to repeat」比較。不要把沒有錯的部分一併重寫。", "reason": "主動 made us clean 不加 to；變被動時要加 to：We were made to clean。", "tip": "主動不加 to；被動 be made to do。", "course": "B 不帶 to 的動詞原形；細項 25。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (60,'{"number": 60, "sentence": "Someone is knocking at the classroom door.", "mark": "tick", "topic": "someone / somebody 單數一致", "wrong": "", "fix": "", "correct_sentence": "Someone is knocking at the classroom door.", "hint": "有人，但不知是哪一個人；找 someone/somebody 所配的動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "someone/somebody 在文法上用單數動詞：Someone is waiting。", "tip": "遇到 someone，先想「某一個人」。", "course": "C 不定代名詞；細項 27。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (61,'{"number": 61, "sentence": "You must not touch the chemicals without gloves.", "mark": "tick", "topic": "must not / mustn’t = 禁止", "wrong": "", "fix": "", "correct_sentence": "You must not touch the chemicals without gloves.", "hint": "告示清楚說不准做一件事。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "must not 表「不准」，不是「沒有必要」；必要時與 do not have to 作比較。", "tip": "看到 No entry / strictly prohibited，想 must not。", "course": "E Must / have to / need to；細項 42。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (62,'{"number": 62, "sentence": "My brother enjoys playing chess.", "mark": "tick", "topic": "第三身單數加 -s", "wrong": "", "fix": "", "correct_sentence": "My brother enjoys playing chess.", "hint": "找真正的主語：he、she、it 或單數名詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般現在式中，第三身單數動詞要用 -s；主語是複數時則不要亂加。", "tip": "用 he/she/it 代替主語，試讀一次動詞。", "course": "A 現在式與現在進行式；細項 03。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (63,'{"number": 63, "sentence": "I hope entering the writing competition.", "mark": "cross", "topic": "want / decide / hope 後用 to + 原形", "wrong": "hope entering", "fix": "hope to enter", "correct_sentence": "I hope to enter the writing competition.", "hint": "找到 want、decide 或 hope 這些表達打算的動詞。", "location": "把原句的「hope entering」圈起來，與同一位置應有的「hope to enter」比較。不要把沒有錯的部分一併重寫。", "reason": "常用 want to、decide to、hope to + 原形；與 enjoy/suggest + -ing 不同。", "tip": "把動詞與後面的結構整組記住。", "course": "G 前置知識與 if 條件句；細項 69。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (64,'{"number": 64, "sentence": "Our class visited the Hong Kong Science Museum.", "mark": "tick", "topic": "冠詞：a / an / the / 零冠詞", "wrong": "", "fix": "", "correct_sentence": "Our class visited the Hong Kong Science Museum.", "hint": "先問名詞是否第一次出現、是否特定，再聽開首讀音。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "a/an 常用於首次提及的單數可數名詞；the 指已知或特定；某些固定用法不加冠詞。", "tip": "a university（/y/ 音）、an honest answer（h 不發音）、the UK。", "course": "G 前置知識與 if 條件句；細項 75。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (65,'{"number": 65, "sentence": "Unless the weather changes, we will visit the island tomorrow.", "mark": "tick", "topic": "unless 後談將來常用現在式", "wrong": "", "fix": "", "correct_sentence": "Unless the weather changes, we will visit the island tomorrow.", "hint": "前面 unless 子句是在講將來可能出現的條件。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般未來條件句中，unless 後通常用現在式；結果部分才用 will + 原形。", "tip": "Unless it rains, we will go；不要 Unless it will rain。", "course": "D Unless 條件句；細項 36。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (66,'{"number": 66, "sentence": "If you will finish early, you will have time to revise.", "mark": "cross", "topic": "First conditional：真實可能的將來", "wrong": "you will finish", "fix": "you finish", "correct_sentence": "If you finish early, you will have time to revise.", "hint": "if 子句說將來有可能發生的情況，主句有 will。", "location": "把原句的「you will finish」圈起來，與同一位置應有的「you finish」比較。不要把沒有錯的部分一併重寫。", "reason": "常用 if + 現在式，will + 原形；if 子句一般不直接用 will 表普通未來。", "tip": "If it rains, we will stay inside。", "course": "G 前置知識與 if 條件句；細項 71。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (67,'{"number": 67, "sentence": "Do not leave until the teacher has checked your work.", "mark": "tick", "topic": "unless 與 until 不同", "wrong": "", "fix": "", "correct_sentence": "Do not leave until the teacher has checked your work.", "hint": "中文的「直到」和「除非」不同；看句子是否表達時間還是條件。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "until = 直到某時；unless = 除非某條件。They waited until the rain stopped 不是 unless。", "tip": "如果可以問「等到幾時？」就檢查 until。", "course": "D Unless 條件句；細項 38。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (68,'{"number": 68, "sentence": "My aunt has worked in UK for ten years.", "mark": "cross", "topic": "冠詞：a / an / the / 零冠詞", "wrong": "UK", "fix": "the UK", "correct_sentence": "My aunt has worked in the UK for ten years.", "hint": "先問名詞是否第一次出現、是否特定，再聽開首讀音。", "location": "把原句的「UK」圈起來，與同一位置應有的「the UK」比較。不要把沒有錯的部分一併重寫。", "reason": "a/an 常用於首次提及的單數可數名詞；the 指已知或特定；某些固定用法不加冠詞。", "tip": "a university（/y/ 音）、an honest answer（h 不發音）、the UK。", "course": "G 前置知識與 if 條件句；細項 75。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (69,'{"number": 69, "sentence": "Somebody has put a note on my desk.", "mark": "tick", "topic": "肯定句的 somebody / something", "wrong": "", "fix": "", "correct_sentence": "Somebody has put a note on my desk.", "hint": "句子在肯定地說有某個人或某件東西。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "肯定句介紹某人或某事常用 somebody/something；any- 也可能有「任何」意思，須靠語境，不可機械地當錯。", "tip": "想「有人／某件事」時，先考慮 some-。", "course": "C 不定代名詞；細項 32。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (70,'{"number": 70, "sentence": "Amy is interested in learn sign language.", "mark": "cross", "topic": "介詞後用 -ing（動名詞）", "wrong": "in learn", "fix": "in learning", "correct_sentence": "Amy is interested in learning sign language.", "hint": "留意 look forward to、interested in、good at 等搭配。", "location": "把原句的「in learn」圈起來，與同一位置應有的「in learning」比較。不要把沒有錯的部分一併重寫。", "reason": "介詞後接名詞或動名詞 -ing：interested in reading；其中 look forward to 的 to 是介詞。", "tip": "先判斷 to 是介詞還是不定式標誌。", "course": "G 前置知識與 if 條件句；細項 67。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (71,'{"number": 71, "sentence": "If plants do not get sunlight, they grows poorly.", "mark": "cross", "topic": "Zero conditional：事實與規律", "wrong": "grows", "fix": "grow", "correct_sentence": "If plants do not get sunlight, they grow poorly.", "hint": "if 子句與主句都描述反覆成立的事實或規律。", "location": "把原句的「grows」圈起來，與同一位置應有的「grow」比較。不要把沒有錯的部分一併重寫。", "reason": "零類條件句常用 if + 現在式，主句也用現在式：If you heat ice, it melts。", "tip": "先想「每次這樣就會那樣」是否屬規律。", "course": "G 前置知識與 if 條件句；細項 70。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (72,'{"number": 72, "sentence": "If I had more free time, I would join the drama club.", "mark": "tick", "topic": "Second conditional：假設／不太可能", "wrong": "", "fix": "", "correct_sentence": "If I had more free time, I would join the drama club.", "hint": "if 子句在提出假設，主句用 would + 原形。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "第二類常用 if + 過去式，would + 原形；這個過去式不一定表示過去時間。", "tip": "If I had more time, I would read more。", "course": "G 前置知識與 if 條件句；細項 72。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (73,'{"number": 73, "sentence": "None the pupils forgot their homework today.", "mark": "cross", "topic": "none of / another / the other", "wrong": "None the pupils", "fix": "None of the pupils", "correct_sentence": "None of the pupils forgot their homework today.", "hint": "看 none 後有沒有 of；再看 another 後的單數名詞及已經提過的兩件物件。", "location": "把原句的「None the pupils」圈起來，與同一位置應有的「None of the pupils」比較。不要把沒有錯的部分一併重寫。", "reason": "none of + 指定的一群人／東西；another + 單數可數名詞表示另外一個；若明確只有兩個，第二個通常叫 the other。", "tip": "背短語：none of the books；another chair；one ... the other。", "course": "C 不定代名詞；細項 40。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (74,'{"number": 74, "sentence": "We must not bring our own microphones because the school will provide them.", "mark": "cross", "topic": "do not need to = 無須", "wrong": "must not", "fix": "do not need to", "correct_sentence": "We do not need to bring our own microphones because the school will provide them.", "hint": "句子要說一件事不是必需的，並不代表禁止。", "location": "把原句的「must not」圈起來，與同一位置應有的「do not need to」比較。不要把沒有錯的部分一併重寫。", "reason": "do/does not need to + 原形，表示不用做；與 must not（禁止）分開。", "tip": "「不用」≠「不准」。", "course": "E Must / have to / need to；細項 47。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (75,'{"number": 75, "sentence": "Jenny studies French after school.", "mark": "tick", "topic": "第三身 -es 與 -ies 拼字", "wrong": "", "fix": "", "correct_sentence": "Jenny studies French after school.", "hint": "主語是單數；注意動詞結尾 ch、sh、o 或 consonant + y。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "watch → watches；study → studies。不是任何動詞都只直接加 -s。", "tip": "先看字尾，再決定加 -s、-es 或改 y 為 ies。", "course": "A 現在式與現在進行式；細項 04。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (76,'{"number": 76, "sentence": "We are makeing posters for the charity fair.", "mark": "cross", "topic": "-ing 的拼字變化", "wrong": "makeing", "fix": "making", "correct_sentence": "We are making posters for the charity fair.", "hint": "已確定要用進行式，再檢查動詞的 -ing 拼字。", "location": "把原句的「makeing」圈起來，與同一位置應有的「making」比較。不要把沒有錯的部分一併重寫。", "reason": "write → writing（去 e）；run → running（雙寫 n）；lie → lying（ie 變 y）。", "tip": "先選正確時態，再看字尾拼法。", "course": "A 現在式與現在進行式；細項 10。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (77,'{"number": 77, "sentence": "Every monitor has to submit the attendance list.", "mark": "tick", "topic": "he / she / it has to", "wrong": "", "fix": "", "correct_sentence": "Every monitor has to submit the attendance list.", "hint": "主語是單數，看看 have to 要不要變 has to。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "have to 不是情態動詞 must；一般現在式 he/she/it 要用 has to。", "tip": "he has to；they have to。", "course": "E Must / have to / need to；細項 43。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (78,'{"number": 78, "sentence": "The number of visitors increase steadily this year.", "mark": "cross", "topic": "正在改變的情況及趨勢", "wrong": "increase", "fix": "is increasing", "correct_sentence": "The number of visitors is increasing steadily this year.", "hint": "留意 gradually、these days、more and more 等表示變化中的字。", "location": "把原句的「increase」圈起來，與同一位置應有的「is increasing」比較。不要把沒有錯的部分一併重寫。", "reason": "強調現正發展的趨勢時，通常用現在進行式；它不同於永遠不變的事實。", "tip": "想像有一條上升／下降中的線：is increasing。", "course": "A 現在式與現在進行式；細項 13。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (79,'{"number": 79, "sentence": "Each classroom have an emergency exit.", "mark": "cross", "topic": "第三身單數加 -s", "wrong": "have", "fix": "has", "correct_sentence": "Each classroom has an emergency exit.", "hint": "找真正的主語：he、she、it 或單數名詞。", "location": "把原句的「have」圈起來，與同一位置應有的「has」比較。不要把沒有錯的部分一併重寫。", "reason": "一般現在式中，第三身單數動詞要用 -s；主語是複數時則不要亂加。", "tip": "用 he/she/it 代替主語，試讀一次動詞。", "course": "A 現在式與現在進行式；細項 03。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (80,'{"number": 80, "sentence": "Everyone enjoys the school picnic.", "mark": "tick", "topic": "everyone / everybody 用單數動詞", "wrong": "", "fix": "", "correct_sentence": "Everyone enjoys the school picnic.", "hint": "留意 everyone、everybody 雖然指很多人，文法上當單數。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "everyone/everybody + is/has/動詞-s；不能因為意思是「所有人」而用 are。", "tip": "把 everyone 當作 he/she 來試配動詞。", "course": "C 不定代名詞；細項 26。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (81,'{"number": 81, "sentence": "The head teacher gave an honest answer to the question.", "mark": "tick", "topic": "冠詞：a / an / the / 零冠詞", "wrong": "", "fix": "", "correct_sentence": "The head teacher gave an honest answer to the question.", "hint": "先問名詞是否第一次出現、是否特定，再聽開首讀音。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "a/an 常用於首次提及的單數可數名詞；the 指已知或特定；某些固定用法不加冠詞。", "tip": "a university（/y/ 音）、an honest answer（h 不發音）、the UK。", "course": "G 前置知識與 if 條件句；細項 75。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (82,'{"number": 82, "sentence": "Nobody wants to miss the final match.", "mark": "tick", "topic": "nobody / no one + 單數動詞", "wrong": "", "fix": "", "correct_sentence": "Nobody wants to miss the final match.", "hint": "句子主語是 nobody / no one。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "nobody/no one 雖然表示沒有人，仍用單數動詞：Nobody knows。", "tip": "不要見到「沒有人」就誤用複數動詞。", "course": "C 不定代名詞；細項 28。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (83,'{"number": 83, "sentence": "I think the weather will to improve by lunchtime.", "mark": "cross", "topic": "will + 動詞原形：未來", "wrong": "will to improve", "fix": "will improve", "correct_sentence": "I think the weather will improve by lunchtime.", "hint": "留意承諾、預測、即時決定，並檢查 will 後的動詞。", "location": "把原句的「will to improve」圈起來，與同一位置應有的「will improve」比較。不要把沒有錯的部分一併重寫。", "reason": "will 後直接跟動詞原形，不加 to，也不變 -s/-ed。", "tip": "will go、will help、will arrive。", "course": "G 前置知識與 if 條件句；細項 65。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (84,'{"number": 84, "sentence": "If she will practise more, she would feel more confident.", "mark": "cross", "topic": "Second conditional：假設／不太可能", "wrong": "she will practise", "fix": "she practised", "correct_sentence": "If she practised more, she would feel more confident.", "hint": "if 子句在提出假設，主句用 would + 原形。", "location": "把原句的「she will practise」圈起來，與同一位置應有的「she practised」比較。不要把沒有錯的部分一併重寫。", "reason": "第二類常用 if + 過去式，would + 原形；這個過去式不一定表示過去時間。", "tip": "If I had more time, I would read more。", "course": "G 前置知識與 if 條件句；細項 72。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (85,'{"number": 85, "sentence": "Does your cousin live near the station?", "mark": "tick", "topic": "現在式問句：do / does", "wrong": "", "fix": "", "correct_sentence": "Does your cousin live near the station?", "hint": "看句子是不是一般現在式的疑問句，並找 do/does 後的主語。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般動詞的現在式問句通常要 do/does；does 後面的主要動詞回到原形。", "tip": "記住：Does she PLAY? 不是 Does she PLAYS?", "course": "A 現在式與現在進行式；細項 05。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (86,'{"number": 86, "sentence": "Something have changed in the new timetable.", "mark": "cross", "topic": "everything / something 單數一致", "wrong": "have", "fix": "has", "correct_sentence": "Something has changed in the new timetable.", "hint": "everything、something 指事物，但當作單數。", "location": "把原句的「have」圈起來，與同一位置應有的「has」比較。不要把沒有錯的部分一併重寫。", "reason": "Everything is ready，Something looks strange；不能用 are 或 look（原形）配單數主語。", "tip": "以 it 代替 everything 試試動詞。", "course": "C 不定代名詞；細項 29。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (87,'{"number": 87, "sentence": "We will go swimming unless the pool closes early.", "mark": "tick", "topic": "unless 後談將來常用現在式", "wrong": "", "fix": "", "correct_sentence": "We will go swimming unless the pool closes early.", "hint": "前面 unless 子句是在講將來可能出現的條件。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般未來條件句中，unless 後通常用現在式；結果部分才用 will + 原形。", "tip": "Unless it rains, we will go；不要 Unless it will rain。", "course": "D Unless 條件句；細項 36。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (88,'{"number": 88, "sentence": "We cannot find anything in the empty cupboard.", "mark": "tick", "topic": "否定句常用 anything / anybody", "wrong": "", "fix": "", "correct_sentence": "We cannot find anything in the empty cupboard.", "hint": "句子前面已有 not 或 never，看看後面用甚麼不定代名詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "在一般否定句，通常說 do not have anything、did not see anybody；不用雙重否定。", "tip": "前面有 not，後面優先檢查 any- 字頭。", "course": "C 不定代名詞；細項 30。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (89,'{"number": 89, "sentence": "If she has revised the notes, she would have answered correctly.", "mark": "cross", "topic": "Third conditional：對過去的假設", "wrong": "has revised", "fix": "had revised", "correct_sentence": "If she had revised the notes, she would have answered correctly.", "hint": "句子是在想「如果當時……就好了」，但事情已不可能改變。", "location": "把原句的「has revised」圈起來，與同一位置應有的「had revised」比較。不要把沒有錯的部分一併重寫。", "reason": "常用 if + had + 過去分詞，would have + 過去分詞。", "tip": "過去沒有發生的事：If I had studied, I would have passed。", "course": "G 前置知識與 if 條件句；細項 73。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (90,'{"number": 90, "sentence": "The bell rang, so everyone returned to class.", "mark": "tick", "topic": "so 表結果，不是 so to + 動詞", "wrong": "", "fix": "", "correct_sentence": "The bell rang, so everyone returned to class.", "hint": "看看 so 後是不是直接跟着 to + 動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "so 通常連接結果子句；表示目的要用 so as to + 原形，不能隨意寫 so to。", "tip": "so + 完整句；so as to + 原形。", "course": "F So / so that / so as to；細項 52。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (91,'{"number": 91, "sentence": "I heard somebody calling for help outside.", "mark": "tick", "topic": "肯定句的 somebody / something", "wrong": "", "fix": "", "correct_sentence": "I heard somebody calling for help outside.", "hint": "句子在肯定地說有某個人或某件東西。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "肯定句介紹某人或某事常用 somebody/something；any- 也可能有「任何」意思，須靠語境，不可機械地當錯。", "tip": "想「有人／某件事」時，先考慮 some-。", "course": "C 不定代名詞；細項 32。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (92,'{"number": 92, "sentence": "Something smell delicious in the kitchen.", "mark": "cross", "topic": "everything / something 單數一致", "wrong": "smell", "fix": "smells", "correct_sentence": "Something smells delicious in the kitchen.", "hint": "everything、something 指事物，但當作單數。", "location": "把原句的「smell」圈起來，與同一位置應有的「smells」比較。不要把沒有錯的部分一併重寫。", "reason": "Everything is ready，Something looks strange；不能用 are 或 look（原形）配單數主語。", "tip": "以 it 代替 everything 試試動詞。", "course": "C 不定代名詞；細項 29。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (93,'{"number": 93, "sentence": "We should to discuss the problem calmly.", "mark": "cross", "topic": "should / may / might 後原形", "wrong": "should to discuss", "fix": "should discuss", "correct_sentence": "We should discuss the problem calmly.", "hint": "找到 should、may 或 might；它們都屬情態動詞。", "location": "把原句的「should to discuss」圈起來，與同一位置應有的「should discuss」比較。不要把沒有錯的部分一併重寫。", "reason": "should/may/might 後面直接接原形，不要多加 to 或 -ing。", "tip": "試用 should go、may leave、might rain 記憶。", "course": "B 不帶 to 的動詞原形；細項 18。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (94,'{"number": 94, "sentence": "I submitted my art project yesterday afternoon.", "mark": "tick", "topic": "一般過去式：已完結的時間", "wrong": "", "fix": "", "correct_sentence": "I submitted my art project yesterday afternoon.", "hint": "留意 yesterday、last week、two days ago，事情已經結束。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "特定過去時間發生的事件通常用一般過去式；不要混用現在完成式。", "tip": "看到 ago，先想到 did，而不是 have done。", "course": "G 前置知識與 if 條件句；細項 59。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (95,'{"number": 95, "sentence": "She won two awards this term so far.", "mark": "cross", "topic": "現在完成式：至今的成果", "wrong": "won", "fix": "has won", "correct_sentence": "She has won two awards this term so far.", "hint": "留意 so far、up to now、since 等與現在仍有關係的時間線索。", "location": "把原句的「won」圈起來，與同一位置應有的「has won」比較。不要把沒有錯的部分一併重寫。", "reason": "have/has + 過去分詞，說明以前發生而與現在有關的結果。", "tip": "「至今」想 have/has done；「昨天」想 did。", "course": "G 前置知識與 if 條件句；細項 63。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (96,'{"number": 96, "sentence": "Plants are needing sunlight to grow.", "mark": "cross", "topic": "一般事實及科學真理", "wrong": "are needing", "fix": "need", "correct_sentence": "Plants need sunlight to grow.", "hint": "句子在講普遍成立的事實，而不是某個人此刻正在做的事。", "location": "把原句的「are needing」圈起來，與同一位置應有的「need」比較。不要把沒有錯的部分一併重寫。", "reason": "科學事實、定義、自然規律常用一般現在式；沒有理由就不要改成現在進行式。", "tip": "先想：「這句話明天也通常成立嗎？」成立就傾向用現在式。", "course": "A 現在式與現在進行式；細項 02。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (97,'{"number": 97, "sentence": "Our regular teacher teaches Maths, but a substitute is teaching us today.", "mark": "tick", "topic": "短期情況與長期習慣", "wrong": "", "fix": "", "correct_sentence": "Our regular teacher teaches Maths, but a substitute is teaching us today.", "hint": "留意 this week、this month、for now 和 usually 的對比。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "平常習慣用現在式；只在這段時間暫時發生的事情常用進行式。", "tip": "把「通常」和「暫時」在心中分開。", "course": "A 現在式與現在進行式；細項 12。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (98,'{"number": 98, "sentence": "Our captain does not has to collect the fees this week.", "mark": "cross", "topic": "does not have to + 原形", "wrong": "does not has", "fix": "does not have", "correct_sentence": "Our captain does not have to collect the fees this week.", "hint": "主語是 he/she/it，而句子要說「不必」。", "location": "把原句的「does not has」圈起來，與同一位置應有的「does not have」比較。不要把沒有錯的部分一併重寫。", "reason": "does not have to + 原形；前面有 does 時，不能說 doesn’t has to。", "tip": "does 已經負責第三身單數，have 不再變 has。", "course": "E Must / have to / need to；細項 45。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (99,'{"number": 99, "sentence": "You must not attend the optional workshop.", "mark": "cross", "topic": "do not have to = 不必", "wrong": "must not", "fix": "do not have to", "correct_sentence": "You do not have to attend the optional workshop.", "hint": "句子在說「可以選擇」，不是「禁止」。", "location": "把原句的「must not」圈起來，與同一位置應有的「do not have to」比較。不要把沒有錯的部分一併重寫。", "reason": "do not have to = 沒有必要做；must not = 不准做。兩者意思完全不同。", "tip": "問：「可不可以做？」可以但不必 = don’t have to。", "course": "E Must / have to / need to；細項 44。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (100,'{"number": 100, "sentence": "Our team lost the match last Saturday.", "mark": "tick", "topic": "一般過去式：已完結的時間", "wrong": "", "fix": "", "correct_sentence": "Our team lost the match last Saturday.", "hint": "留意 yesterday、last week、two days ago，事情已經結束。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "特定過去時間發生的事件通常用一般過去式；不要混用現在完成式。", "tip": "看到 ago，先想到 did，而不是 have done。", "course": "G 前置知識與 if 條件句；細項 59。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (101,'{"number": 101, "sentence": "My sister do not like noisy places.", "mark": "cross", "topic": "現在式否定：do not / does not", "wrong": "do not", "fix": "does not", "correct_sentence": "My sister does not like noisy places.", "hint": "找 not 前面的助動詞，留意主語單複數。", "location": "把原句的「do not」圈起來，與同一位置應有的「does not」比較。不要把沒有錯的部分一併重寫。", "reason": "he/she/it 用 does not + 原形；I/you/we/they 用 do not + 原形。", "tip": "把「doesn''t + 原形」當成一組。", "course": "A 現在式與現在進行式；細項 06。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (102,'{"number": 102, "sentence": "The concert starting at seven tonight.", "mark": "cross", "topic": "時間表：將來活動可用現在式", "wrong": "starting", "fix": "starts", "correct_sentence": "The concert starts at seven tonight.", "hint": "句子談巴士、課堂、電影等固定時間表。", "location": "把原句的「starting」圈起來，與同一位置應有的「starts」比較。不要把沒有錯的部分一併重寫。", "reason": "已訂好的時間表即使在未來，也可以用一般現在式：The train leaves at six。", "tip": "看「固定時間表」而不只是看到 tomorrow 就改 will。", "course": "A 現在式與現在進行式；細項 08。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (103,'{"number": 103, "sentence": "Someone leave a thank-you card for our teacher.", "mark": "cross", "topic": "肯定句的 somebody / something", "wrong": "leave", "fix": "left", "correct_sentence": "Someone left a thank-you card for our teacher.", "hint": "句子在肯定地說有某個人或某件東西。", "location": "把原句的「leave」圈起來，與同一位置應有的「left」比較。不要把沒有錯的部分一併重寫。", "reason": "肯定句介紹某人或某事常用 somebody/something；any- 也可能有「任何」意思，須靠語境，不可機械地當錯。", "tip": "想「有人／某件事」時，先考慮 some-。", "course": "C 不定代名詞；細項 32。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (104,'{"number": 104, "sentence": "Unless we save the file, we may lose our work.", "mark": "tick", "topic": "unless 的邏輯：不要誤加 not", "wrong": "", "fix": "", "correct_sentence": "Unless we save the file, we may lose our work.", "hint": "看 unless 後面的否定字會不會把原意倒轉。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "unless 已含「如果不」；若再加 not，整句條件會變成另一種意思，不是每次都錯，必須用上下文判斷。", "tip": "先把 unless 改寫成 if not，再檢查有沒有兩個「不」。", "course": "D Unless 條件句；細項 37。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (105,'{"number": 105, "sentence": "Is there anything else you need to finish?", "mark": "tick", "topic": "問句的 anybody / anything", "wrong": "", "fix": "", "correct_sentence": "Is there anything else you need to finish?", "hint": "普通問句在詢問是否有人／有東西，答案未知。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般中性問句多用 anyone/anybody/anything；但邀請或期待肯定回應的問句可以用 some-，不要一概硬改。", "tip": "先分清「中性查詢」還是「禮貌邀請」。", "course": "C 不定代名詞；細項 31。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (106,'{"number": 106, "sentence": "Somebody have left a jacket in the library.", "mark": "cross", "topic": "someone / somebody 單數一致", "wrong": "have", "fix": "has", "correct_sentence": "Somebody has left a jacket in the library.", "hint": "有人，但不知是哪一個人；找 someone/somebody 所配的動詞。", "location": "把原句的「have」圈起來，與同一位置應有的「has」比較。不要把沒有錯的部分一併重寫。", "reason": "someone/somebody 在文法上用單數動詞：Someone is waiting。", "tip": "遇到 someone，先想「某一個人」。", "course": "C 不定代名詞；細項 27。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (107,'{"number": 107, "sentence": "Does the new student speaks Cantonese?", "mark": "cross", "topic": "現在式問句：do / does", "wrong": "speaks", "fix": "speak", "correct_sentence": "Does the new student speak Cantonese?", "hint": "看句子是不是一般現在式的疑問句，並找 do/does 後的主語。", "location": "把原句的「speaks」圈起來，與同一位置應有的「speak」比較。不要把沒有錯的部分一併重寫。", "reason": "一般動詞的現在式問句通常要 do/does；does 後面的主要動詞回到原形。", "tip": "記住：Does she PLAY? 不是 Does she PLAYS?", "course": "A 現在式與現在進行式；細項 05。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (108,'{"number": 108, "sentence": "We needn’t to pay for the free museum tour.", "mark": "cross", "topic": "needn’t 後直接原形", "wrong": "needn’t to pay", "fix": "needn’t pay", "correct_sentence": "We needn’t pay for the free museum tour.", "hint": "這是情態用法 needn’t，與 don’t need to 結構不同。", "location": "把原句的「needn’t to pay」圈起來，與同一位置應有的「needn’t pay」比較。不要把沒有錯的部分一併重寫。", "reason": "needn’t + 原形，不加 to；例 needn’t worry。", "tip": "分清 needn’t go 與 don’t need to go。", "course": "E Must / have to / need to；細項 48。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (109,'{"number": 109, "sentence": "Does the captain have to attend every practice?", "mark": "tick", "topic": "have to 問句用 do/does", "wrong": "", "fix": "", "correct_sentence": "Does the captain have to attend every practice?", "hint": "句子在問某人是否必須做某事。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般現在式問句用 Do/Does + 主語 + have to + 原形；不是 Does she has to。", "tip": "Does he have to go? 一口氣檢查兩個地方。", "course": "E Must / have to / need to；細項 50。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (110,'{"number": 110, "sentence": "If I had seen the message, I would replied sooner.", "mark": "cross", "topic": "Third conditional：對過去的假設", "wrong": "would replied", "fix": "would have replied", "correct_sentence": "If I had seen the message, I would have replied sooner.", "hint": "句子是在想「如果當時……就好了」，但事情已不可能改變。", "location": "把原句的「would replied」圈起來，與同一位置應有的「would have replied」比較。不要把沒有錯的部分一併重寫。", "reason": "常用 if + had + 過去分詞，would have + 過去分詞。", "tip": "過去沒有發生的事：If I had studied, I would have passed。", "course": "G 前置知識與 if 條件句；細項 73。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (111,'{"number": 111, "sentence": "If I were the captain, I would listen to every teammate.", "mark": "tick", "topic": "Second conditional：假設／不太可能", "wrong": "", "fix": "", "correct_sentence": "If I were the captain, I would listen to every teammate.", "hint": "if 子句在提出假設，主句用 would + 原形。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "第二類常用 if + 過去式，would + 原形；這個過去式不一定表示過去時間。", "tip": "If I had more time, I would read more。", "course": "G 前置知識與 if 條件句；細項 72。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (112,'{"number": 112, "sentence": "Sara staying with her aunt this month while her flat is repaired.", "mark": "cross", "topic": "短期情況與長期習慣", "wrong": "staying", "fix": "is staying", "correct_sentence": "Sara is staying with her aunt this month while her flat is repaired.", "hint": "留意 this week、this month、for now 和 usually 的對比。", "location": "把原句的「staying」圈起來，與同一位置應有的「is staying」比較。不要把沒有錯的部分一併重寫。", "reason": "平常習慣用現在式；只在這段時間暫時發生的事情常用進行式。", "tip": "把「通常」和「暫時」在心中分開。", "course": "A 現在式與現在進行式；細項 12。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (113,'{"number": 113, "sentence": "If it rains tomorrow, we will hold the ceremony indoors.", "mark": "tick", "topic": "First conditional：真實可能的將來", "wrong": "", "fix": "", "correct_sentence": "If it rains tomorrow, we will hold the ceremony indoors.", "hint": "if 子句說將來有可能發生的情況，主句有 will。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "常用 if + 現在式，will + 原形；if 子句一般不直接用 will 表普通未來。", "tip": "If it rains, we will stay inside。", "course": "G 前置知識與 if 條件句；細項 71。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (114,'{"number": 114, "sentence": "The school provides ramps so that wheelchair users can enter safely.", "mark": "tick", "topic": "so that + can：現在目的", "wrong": "", "fix": "", "correct_sentence": "The school provides ramps so that wheelchair users can enter safely.", "hint": "句子在說現在／將來的目的，目標是「能夠做到」。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "用 so that + 人 + can + 原形：I speak clearly so that you can hear。", "tip": "目的句中 can 後不可加 to。", "course": "F So / so that / so as to；細項 54。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (115,'{"number": 115, "sentence": "She needn’t stay if she has already finished.", "mark": "tick", "topic": "needn’t 後直接原形", "wrong": "", "fix": "", "correct_sentence": "She needn’t stay if she has already finished.", "hint": "這是情態用法 needn’t，與 don’t need to 結構不同。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "needn’t + 原形，不加 to；例 needn’t worry。", "tip": "分清 needn’t go 與 don’t need to go。", "course": "E Must / have to / need to；細項 48。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (116,'{"number": 116, "sentence": "Mum lets my brother chooses his own lunch.", "mark": "cross", "topic": "let + 人 + 動詞原形", "wrong": "lets my brother chooses", "fix": "lets my brother choose", "correct_sentence": "Mum lets my brother choose his own lunch.", "hint": "找到 let，特別留意 let us / let me / let him 後面的動詞。", "location": "把原句的「lets my brother chooses」圈起來，與同一位置應有的「lets my brother choose」比較。不要把沒有錯的部分一併重寫。", "reason": "let someone do something，後面通常不用 to；例如 let me try。", "tip": "let + 人 + 原形，三件事排在一起。", "course": "B 不帶 to 的動詞原形；細項 20。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (117,'{"number": 117, "sentence": "If they had checked the lights, the show would have started on time.", "mark": "tick", "topic": "Third conditional：對過去的假設", "wrong": "", "fix": "", "correct_sentence": "If they had checked the lights, the show would have started on time.", "hint": "句子是在想「如果當時……就好了」，但事情已不可能改變。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "常用 if + had + 過去分詞，would have + 過去分詞。", "tip": "過去沒有發生的事：If I had studied, I would have passed。", "course": "G 前置知識與 if 條件句；細項 73。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (118,'{"number": 118, "sentence": "The coach made the players to run another lap.", "mark": "cross", "topic": "主動 make + 人 + 動詞原形", "wrong": "made the players to run", "fix": "made the players run", "correct_sentence": "The coach made the players run another lap.", "hint": "句子的意思是「令某人做某事」，而 make 是主動式。", "location": "把原句的「made the players to run」圈起來，與同一位置應有的「made the players run」比較。不要把沒有錯的部分一併重寫。", "reason": "make/made someone do something；主動使役用原形，不用 to do。", "tip": "made us clean；不要 made us to clean。", "course": "B 不帶 to 的動詞原形；細項 21。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (119,'{"number": 119, "sentence": "She have to arrive fifteen minutes early.", "mark": "cross", "topic": "he / she / it has to", "wrong": "have to", "fix": "has to", "correct_sentence": "She has to arrive fifteen minutes early.", "hint": "主語是單數，看看 have to 要不要變 has to。", "location": "把原句的「have to」圈起來，與同一位置應有的「has to」比較。不要把沒有錯的部分一併重寫。", "reason": "have to 不是情態動詞 must；一般現在式 he/she/it 要用 has to。", "tip": "he has to；they have to。", "course": "E Must / have to / need to；細項 43。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (120,'{"number": 120, "sentence": "Our school library opens at eight every weekday.", "mark": "tick", "topic": "現在習慣：頻率副詞", "wrong": "", "fix": "", "correct_sentence": "Our school library opens at eight every weekday.", "hint": "留意 usually、often、every morning 等字；它們在說日常習慣。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "習慣是反覆發生的事，通常用一般現在式，不用過去式或為了「正在」而硬加 -ing。", "tip": "看到頻率字，先問「是天天如此，還是此刻一次？」", "course": "A 現在式與現在進行式；細項 01。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (121,'{"number": 121, "sentence": "A heavy storm struck the coast last night.", "mark": "tick", "topic": "不規則過去式", "wrong": "", "fix": "", "correct_sentence": "A heavy storm struck the coast last night.", "hint": "句子已有明確過去時間；找動詞的過去式是否拼對。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "有些動詞不直接加 -ed，例如 strike → struck、go → went、bring → brought。", "tip": "常錯的動詞三態要逐個背，不能一律加 -ed。", "course": "G 前置知識與 if 條件句；細項 60。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (122,'{"number": 122, "sentence": "She did not buy nothing at the book fair.", "mark": "cross", "topic": "否定句常用 anything / anybody", "wrong": "nothing", "fix": "anything", "correct_sentence": "She did not buy anything at the book fair.", "hint": "句子前面已有 not 或 never，看看後面用甚麼不定代名詞。", "location": "把原句的「nothing」圈起來，與同一位置應有的「anything」比較。不要把沒有錯的部分一併重寫。", "reason": "在一般否定句，通常說 do not have anything、did not see anybody；不用雙重否定。", "tip": "前面有 not，後面優先檢查 any- 字頭。", "course": "C 不定代名詞；細項 30。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (123,'{"number": 123, "sentence": "The students decided to postpone the trip.", "mark": "tick", "topic": "want / decide / hope 後用 to + 原形", "wrong": "", "fix": "", "correct_sentence": "The students decided to postpone the trip.", "hint": "找到 want、decide 或 hope 這些表達打算的動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "常用 want to、decide to、hope to + 原形；與 enjoy/suggest + -ing 不同。", "tip": "把動詞與後面的結構整組記住。", "course": "G 前置知識與 if 條件句；細項 69。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (124,'{"number": 124, "sentence": "My brother is good at drawing cartoons.", "mark": "tick", "topic": "介詞後用 -ing（動名詞）", "wrong": "", "fix": "", "correct_sentence": "My brother is good at drawing cartoons.", "hint": "留意 look forward to、interested in、good at 等搭配。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "介詞後接名詞或動名詞 -ing：interested in reading；其中 look forward to 的 to 是介詞。", "tip": "先判斷 to 是介詞還是不定式標誌。", "course": "G 前置知識與 if 條件句；細項 67。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (125,'{"number": 125, "sentence": "When I reached the station, the train had already left.", "mark": "tick", "topic": "過去完成式：比另一過去事件更早", "wrong": "", "fix": "", "correct_sentence": "When I reached the station, the train had already left.", "hint": "留意 by the time + 過去動詞；有兩件在過去發生的事。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "過去完成式 had + 過去分詞，用來說明一件事在另一個過去點前已完成。", "tip": "先發生 had done；後發生 did。", "course": "G 前置知識與 if 條件句；細項 62。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (126,'{"number": 126, "sentence": "We are meeting the guest speaker at four tomorrow.", "mark": "tick", "topic": "已安排的將來：現在進行式", "wrong": "", "fix": "", "correct_sentence": "We are meeting the guest speaker at four tomorrow.", "hint": "留意 tomorrow 或 next week，並且有已約好、已預訂的安排。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "現在進行式亦可說明已安排好的將來約會：We are meeting at four。", "tip": "「已約好」與「只是猜想」不一樣。", "course": "A 現在式與現在進行式；細項 14。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (127,'{"number": 127, "sentence": "We do not need extra chairs today.", "mark": "tick", "topic": "現在式否定：do not / does not", "wrong": "", "fix": "", "correct_sentence": "We do not need extra chairs today.", "hint": "找 not 前面的助動詞，留意主語單複數。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "he/she/it 用 does not + 原形；I/you/we/they 用 do not + 原形。", "tip": "把「doesn''t + 原形」當成一組。", "course": "A 現在式與現在進行式；細項 06。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (128,'{"number": 128, "sentence": "Last month, my sister has to renew her library card.", "mark": "cross", "topic": "過去的必須：had to", "wrong": "has to", "fix": "had to", "correct_sentence": "Last month, my sister had to renew her library card.", "hint": "事情是昨天、去年或上星期發生的強制要求。", "location": "把原句的「has to」圈起來，與同一位置應有的「had to」比較。不要把沒有錯的部分一併重寫。", "reason": "普通義務要談過去，常用 had to；must 不能當作一般動詞變 musted。", "tip": "現在 have to；過去 had to。", "course": "E Must / have to / need to；細項 49。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (129,'{"number": 129, "sentence": "The guard watched the pupils enter the hall.", "mark": "tick", "topic": "感官動詞 see / hear + 人 + 原形", "wrong": "", "fix": "", "correct_sentence": "The guard watched the pupils enter the hall.", "hint": "找 see、saw、hear、heard 後是否接了人，再接動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "描述看見／聽見整個動作，可以用 saw him cross；不能用 saw him to cross。另有 -ing 用法，但意思不同，不能把它當錯。", "tip": "感官動詞 + 人 + 原形；別在中間硬加 to。", "course": "B 不帶 to 的動詞原形；細項 24。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (130,'{"number": 130, "sentence": "While we were walk home, the rain started.", "mark": "cross", "topic": "過去進行式：背景 + 突發事件", "wrong": "were walk", "fix": "were walking", "correct_sentence": "While we were walking home, the rain started.", "hint": "一件事發生時，另一件事情正在進行。", "location": "把原句的「were walk」圈起來，與同一位置應有的「were walking」比較。不要把沒有錯的部分一併重寫。", "reason": "長一點的背景動作用 was/were + -ing；較短的插入事件用一般過去式。", "tip": "一條時間線：was reading → phone rang。", "course": "G 前置知識與 if 條件句；細項 61。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (131,'{"number": 131, "sentence": "The library stays open unless six o’clock.", "mark": "cross", "topic": "unless 與 until 不同", "wrong": "unless", "fix": "until", "correct_sentence": "The library stays open until six o’clock.", "hint": "中文的「直到」和「除非」不同；看句子是否表達時間還是條件。", "location": "把原句的「unless」圈起來，與同一位置應有的「until」比較。不要把沒有錯的部分一併重寫。", "reason": "until = 直到某時；unless = 除非某條件。They waited until the rain stopped 不是 unless。", "tip": "如果可以問「等到幾時？」就檢查 until。", "course": "D Unless 條件句；細項 38。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (132,'{"number": 132, "sentence": "I often revise my notes before dinner.", "mark": "tick", "topic": "現在習慣：頻率副詞", "wrong": "", "fix": "", "correct_sentence": "I often revise my notes before dinner.", "hint": "留意 usually、often、every morning 等字；它們在說日常習慣。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "習慣是反覆發生的事，通常用一般現在式，不用過去式或為了「正在」而硬加 -ing。", "tip": "看到頻率字，先問「是天天如此，還是此刻一次？」", "course": "A 現在式與現在進行式；細項 01。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (133,'{"number": 133, "sentence": "The cyclist slowed down so as not to hit the pedestrians.", "mark": "tick", "topic": "so as not to + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "The cyclist slowed down so as not to hit the pedestrians.", "hint": "句子表示「為了避免某事」，注意 not 的位置。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "正確順序是 so as not to + 原形；not 要放在 to 前。", "tip": "整組背起來：so as not to disturb。", "course": "F So / so that / so as to；細項 57。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (134,'{"number": 134, "sentence": "Our teacher believes that every student can improve.", "mark": "tick", "topic": "狀態動詞：know / believe / understand", "wrong": "", "fix": "", "correct_sentence": "Our teacher believes that every student can improve.", "hint": "句子描述知道、相信、明白的狀態，不是正在進行的動作。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "know、believe、understand 通常不用現在進行式；I know 而非 I am knowing。", "tip": "見到「心裡的狀態」，先別急着加 -ing。", "course": "A 現在式與現在進行式；細項 15。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (135,'{"number": 135, "sentence": "Does your brother doing his homework now?", "mark": "cross", "topic": "進行式疑問句與否定句", "wrong": "Does", "fix": "Is", "correct_sentence": "Is your brother doing his homework now?", "hint": "注意問句的 am/is/are 位置，以及否定句中的 not。", "location": "把原句的「Does」圈起來，與同一位置應有的「Is」比較。不要把沒有錯的部分一併重寫。", "reason": "問句把 be 放主語前：Are they coming?；否定用 is not / are not + -ing。", "tip": "把陳述句 They are waiting 改成問句 Are they waiting? 試一遍。", "course": "A 現在式與現在進行式；細項 11。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (136,'{"number": 136, "sentence": "Somebody want to speak to the principal.", "mark": "cross", "topic": "someone / somebody 單數一致", "wrong": "want", "fix": "wants", "correct_sentence": "Somebody wants to speak to the principal.", "hint": "有人，但不知是哪一個人；找 someone/somebody 所配的動詞。", "location": "把原句的「want」圈起來，與同一位置應有的「wants」比較。不要把沒有錯的部分一併重寫。", "reason": "someone/somebody 在文法上用單數動詞：Someone is waiting。", "tip": "遇到 someone，先想「某一個人」。", "course": "C 不定代名詞；細項 27。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (137,'{"number": 137, "sentence": "We brought torches so that we could to see the path at night.", "mark": "cross", "topic": "so that + could：過去目的", "wrong": "could to see", "fix": "could see", "correct_sentence": "We brought torches so that we could see the path at night.", "hint": "主句說的是已發生的過去行動，目的是讓當時某人能做到某事。", "location": "把原句的「could to see」圈起來，與同一位置應有的「could see」比較。不要把沒有錯的部分一併重寫。", "reason": "常用 so that + 主語 + could + 原形；could 後不能加 to。", "tip": "先確認主句時間，再配 can/could。", "course": "F So / so that / so as to；細項 55。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (138,'{"number": 138, "sentence": "We had better to leave before the heavy rain starts.", "mark": "cross", "topic": "had better + 動詞原形", "wrong": "had better to leave", "fix": "had better leave", "correct_sentence": "We had better leave before the heavy rain starts.", "hint": "留意 had better 這一組提出建議的字。", "location": "把原句的「had better to leave」圈起來，與同一位置應有的「had better leave」比較。不要把沒有錯的部分一併重寫。", "reason": "had better 後直接接原形：had better leave；雖有 had，不表示動詞要用過去式。", "tip": "had better 不加 to。", "course": "B 不帶 to 的動詞原形；細項 22。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (139,'{"number": 139, "sentence": "The students in the music room are rehearsing.", "mark": "tick", "topic": "現在式主謂一致：近距離陷阱", "wrong": "", "fix": "", "correct_sentence": "The students in the music room are rehearsing.", "hint": "找真正主語，不要被中間的 of、with、along with 或長修飾語騙到。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "the number of students 是單數主語 number；the students 是複數；動詞要跟真正主語配合。", "tip": "先遮住主語後面那一長串修飾語。", "course": "G 前置知識與 if 條件句；細項 74。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (140,'{"number": 140, "sentence": "All visitors must show their passes at the entrance.", "mark": "tick", "topic": "must 後接動詞原形", "wrong": "", "fix": "", "correct_sentence": "All visitors must show their passes at the entrance.", "hint": "找到 must，再看緊接的動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "must 後必須用動詞原形，不能接 to 或過去式；例如 must finish。", "tip": "must 後面的動詞不要加 -s、-ed 或 to。", "course": "B 不帶 to 的動詞原形；細項 17。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (141,'{"number": 141, "sentence": "During the examination yesterday, everyone have to remain silent.", "mark": "cross", "topic": "過去的必須：had to", "wrong": "have to", "fix": "had to", "correct_sentence": "During the examination yesterday, everyone had to remain silent.", "hint": "事情是昨天、去年或上星期發生的強制要求。", "location": "把原句的「have to」圈起來，與同一位置應有的「had to」比較。不要把沒有錯的部分一併重寫。", "reason": "普通義務要談過去，常用 had to；must 不能當作一般動詞變 musted。", "tip": "現在 have to；過去 had to。", "course": "E Must / have to / need to；細項 49。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (142,'{"number": 142, "sentence": "I enjoy to read mystery novels on the bus.", "mark": "cross", "topic": "enjoy / avoid / suggest 後用 -ing", "wrong": "enjoy to read", "fix": "enjoy reading", "correct_sentence": "I enjoy reading mystery novels on the bus.", "hint": "找到 enjoy、avoid、suggest，檢查下一個動詞形式。", "location": "把原句的「enjoy to read」圈起來，與同一位置應有的「enjoy reading」比較。不要把沒有錯的部分一併重寫。", "reason": "這類動詞常接動名詞：enjoy reading、avoid making、suggest working。", "tip": "見到三個動詞，先試用 -ing，不要直接加 to。", "course": "G 前置知識與 if 條件句；細項 68。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (143,'{"number": 143, "sentence": "The road was flooded, so to the bus arrived late.", "mark": "cross", "topic": "so + 結果子句", "wrong": "so to the bus", "fix": "so the bus", "correct_sentence": "The road was flooded, so the bus arrived late.", "hint": "句子前半段說原因，後半段描述實際結果。", "location": "把原句的「so to the bus」圈起來，與同一位置應有的「so the bus」比較。不要把沒有錯的部分一併重寫。", "reason": "so 可連接兩個完整子句，表示「所以」：It rained, so we stayed inside。", "tip": "先圈出原因，再圈出結果；so 後應有完整句子。", "course": "F So / so that / so as to；細項 51。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (144,'{"number": 144, "sentence": "The pupils have finished the project before the teacher arrived.", "mark": "cross", "topic": "過去完成式：比另一過去事件更早", "wrong": "have finished", "fix": "had finished", "correct_sentence": "The pupils had finished the project before the teacher arrived.", "hint": "留意 by the time + 過去動詞；有兩件在過去發生的事。", "location": "把原句的「have finished」圈起來，與同一位置應有的「had finished」比較。不要把沒有錯的部分一併重寫。", "reason": "過去完成式 had + 過去分詞，用來說明一件事在另一個過去點前已完成。", "tip": "先發生 had done；後發生 did。", "course": "G 前置知識與 if 條件句；細項 62。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (145,'{"number": 145, "sentence": "The teacher lowered the screen so as to the students see the slides.", "mark": "cross", "topic": "so as to 的動作主語要一致", "wrong": "so as to the students see", "fix": "so that the students could see", "correct_sentence": "The teacher lowered the screen so that the students could see the slides.", "hint": "比較主句誰做動作，以及 so as to 後誰想達到目的。", "location": "把原句的「so as to the students see」圈起來，與同一位置應有的「so that the students could see」比較。不要把沒有錯的部分一併重寫。", "reason": "so as to 的未明說主語通常就是主句主語；若目的是讓另一個人做事，改用 so that + 那個人 + can/could。", "tip": "問兩次「是誰做？」；不同人便考慮 so that。", "course": "F So / so that / so as to；細項 58。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (146,'{"number": 146, "sentence": "The dark clouds show that it going to rain.", "mark": "cross", "topic": "be going to 的完整結構", "wrong": "going", "fix": "is going", "correct_sentence": "The dark clouds show that it is going to rain.", "hint": "留意已有打算或看得到的跡象。", "location": "把原句的「going」圈起來，與同一位置應有的「is going」比較。不要把沒有錯的部分一併重寫。", "reason": "am/is/are going to + 原形；不要漏掉 be，也不要寫 going to + -ing。", "tip": "I am / she is / they are going to do。", "course": "G 前置知識與 if 條件句；細項 66。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (147,'{"number": 147, "sentence": "Please choose another colours for the poster.", "mark": "cross", "topic": "none of / another / the other", "wrong": "another colours", "fix": "another colour", "correct_sentence": "Please choose another colour for the poster.", "hint": "看 none 後有沒有 of；再看 another 後的單數名詞及已經提過的兩件物件。", "location": "把原句的「another colours」圈起來，與同一位置應有的「another colour」比較。不要把沒有錯的部分一併重寫。", "reason": "none of + 指定的一群人／東西；another + 單數可數名詞表示另外一個；若明確只有兩個，第二個通常叫 the other。", "tip": "背短語：none of the books；another chair；one ... the other。", "course": "C 不定代名詞；細項 40。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (148,'{"number": 148, "sentence": "We did not forget the appointment.", "mark": "tick", "topic": "do / does / did 後動詞原形", "wrong": "", "fix": "", "correct_sentence": "We did not forget the appointment.", "hint": "見到 do、does 或 did 是助動詞，後面的主要動詞用原形。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "過去或單數資訊已由 did/does 表示，主要動詞不能再變成 went/plays。", "tip": "Does he go? Did they go? 不能重複標記。", "course": "B 不帶 to 的動詞原形；細項 19。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (149,'{"number": 149, "sentence": "The number of volunteers is increasing this year.", "mark": "tick", "topic": "現在式主謂一致：近距離陷阱", "wrong": "", "fix": "", "correct_sentence": "The number of volunteers is increasing this year.", "hint": "找真正主語，不要被中間的 of、with、along with 或長修飾語騙到。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "the number of students 是單數主語 number；the students 是複數；動詞要跟真正主語配合。", "tip": "先遮住主語後面那一長串修飾語。", "course": "G 前置知識與 if 條件句；細項 74。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (150,'{"number": 150, "sentence": "My brother have to practise the violin tonight.", "mark": "cross", "topic": "he / she / it has to", "wrong": "have to", "fix": "has to", "correct_sentence": "My brother has to practise the violin tonight.", "hint": "主語是單數，看看 have to 要不要變 has to。", "location": "把原句的「have to」圈起來，與同一位置應有的「has to」比較。不要把沒有錯的部分一併重寫。", "reason": "have to 不是情態動詞 must；一般現在式 he/she/it 要用 has to。", "tip": "he has to；they have to。", "course": "E Must / have to / need to；細項 43。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (151,'{"number": 151, "sentence": "The results will appears on the noticeboard tomorrow.", "mark": "cross", "topic": "will + 動詞原形：未來", "wrong": "will appears", "fix": "will appear", "correct_sentence": "The results will appear on the noticeboard tomorrow.", "hint": "留意承諾、預測、即時決定，並檢查 will 後的動詞。", "location": "把原句的「will appears」圈起來，與同一位置應有的「will appear」比較。不要把沒有錯的部分一併重寫。", "reason": "will 後直接跟動詞原形，不加 to，也不變 -s/-ed。", "tip": "will go、will help、will arrive。", "course": "G 前置知識與 if 條件句；細項 65。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (152,'{"number": 152, "sentence": "She flying to Singapore on Friday; her ticket is booked.", "mark": "cross", "topic": "已安排的將來：現在進行式", "wrong": "flying", "fix": "is flying", "correct_sentence": "She is flying to Singapore on Friday; her ticket is booked.", "hint": "留意 tomorrow 或 next week，並且有已約好、已預訂的安排。", "location": "把原句的「flying」圈起來，與同一位置應有的「is flying」比較。不要把沒有錯的部分一併重寫。", "reason": "現在進行式亦可說明已安排好的將來約會：We are meeting at four。", "tip": "「已約好」與「只是猜想」不一樣。", "course": "A 現在式與現在進行式；細項 14。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (153,'{"number": 153, "sentence": "They are understanding why the timetable has changed.", "mark": "cross", "topic": "狀態動詞：know / believe / understand", "wrong": "are understanding", "fix": "understand", "correct_sentence": "They understand why the timetable has changed.", "hint": "句子描述知道、相信、明白的狀態，不是正在進行的動作。", "location": "把原句的「are understanding」圈起來，與同一位置應有的「understand」比較。不要把沒有錯的部分一併重寫。", "reason": "know、believe、understand 通常不用現在進行式；I know 而非 I am knowing。", "tip": "見到「心裡的狀態」，先別急着加 -ing。", "course": "A 現在式與現在進行式；細項 15。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (154,'{"number": 154, "sentence": "My brother can to solve this puzzle quickly.", "mark": "cross", "topic": "can / could 後接動詞原形", "wrong": "can to solve", "fix": "can solve", "correct_sentence": "My brother can solve this puzzle quickly.", "hint": "找到 can 或 could，看看後面的動詞有沒有多加 to、-s 或 -ing。", "location": "把原句的「can to solve」圈起來，與同一位置應有的「can solve」比較。不要把沒有錯的部分一併重寫。", "reason": "can/could 是情態動詞，後面直接跟原形：can swim，不是 can to swim。", "tip": "把 can、could 與下一個動詞連在一起檢查。", "course": "B 不帶 to 的動詞原形；細項 16。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (155,'{"number": 155, "sentence": "Is anything available to lead the tour?", "mark": "cross", "topic": "人用 -one/-body；物用 -thing", "wrong": "anything", "fix": "anybody", "correct_sentence": "Is anybody available to lead the tour?", "hint": "留意動詞的意思：是否在找人，還是在找東西？", "location": "把原句的「anything」圈起來，與同一位置應有的「anybody」比較。不要把沒有錯的部分一併重寫。", "reason": "someone/anyone/nobody 說人；something/anything/nothing 說事物。", "tip": "直接問「要找的是人還是物？」", "course": "C 不定代名詞；細項 33。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (156,'{"number": 156, "sentence": "Do the volunteers arrive early on Fridays?", "mark": "tick", "topic": "現在式問句：do / does", "wrong": "", "fix": "", "correct_sentence": "Do the volunteers arrive early on Fridays?", "hint": "看句子是不是一般現在式的疑問句，並找 do/does 後的主語。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般動詞的現在式問句通常要 do/does；does 後面的主要動詞回到原形。", "tip": "記住：Does she PLAY? 不是 Does she PLAYS?", "course": "A 現在式與現在進行式；細項 05。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (157,'{"number": 157, "sentence": "I am writing clearly so that you can read the instructions.", "mark": "tick", "topic": "so that + can：現在目的", "wrong": "", "fix": "", "correct_sentence": "I am writing clearly so that you can read the instructions.", "hint": "句子在說現在／將來的目的，目標是「能夠做到」。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "用 so that + 人 + can + 原形：I speak clearly so that you can hear。", "tip": "目的句中 can 後不可加 to。", "course": "F So / so that / so as to；細項 54。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (158,'{"number": 158, "sentence": "I am checking the microphone at the moment.", "mark": "tick", "topic": "進行式：am/is/are + -ing", "wrong": "", "fix": "", "correct_sentence": "I am checking the microphone at the moment.", "hint": "留意 right now、at the moment；找主語、be 和 -ing 是否齊全。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "現在進行式有兩部分：am/is/are + 動詞-ing；不可只剩 -ing。", "tip": "三步檢查：「誰？」→「am/is/are？」→「-ing？」", "course": "A 現在式與現在進行式；細項 09。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (159,'{"number": 159, "sentence": "The volunteers arrived early so as to prepare the hall.", "mark": "tick", "topic": "so as to 的動作主語要一致", "wrong": "", "fix": "", "correct_sentence": "The volunteers arrived early so as to prepare the hall.", "hint": "比較主句誰做動作，以及 so as to 後誰想達到目的。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "so as to 的未明說主語通常就是主句主語；若目的是讓另一個人做事，改用 so that + 那個人 + can/could。", "tip": "問兩次「是誰做？」；不同人便考慮 so that。", "course": "F So / so that / so as to；細項 58。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (160,'{"number": 160, "sentence": "He left early so that he could caught the last ferry.", "mark": "cross", "topic": "so that + could：過去目的", "wrong": "could caught", "fix": "could catch", "correct_sentence": "He left early so that he could catch the last ferry.", "hint": "主句說的是已發生的過去行動，目的是讓當時某人能做到某事。", "location": "把原句的「could caught」圈起來，與同一位置應有的「could catch」比較。不要把沒有錯的部分一併重寫。", "reason": "常用 so that + 主語 + could + 原形；could 後不能加 to。", "tip": "先確認主句時間，再配 can/could。", "course": "F So / so that / so as to；細項 55。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (161,'{"number": 161, "sentence": "Did the pupils brought their notebooks?", "mark": "cross", "topic": "do / does / did 後動詞原形", "wrong": "brought", "fix": "bring", "correct_sentence": "Did the pupils bring their notebooks?", "hint": "見到 do、does 或 did 是助動詞，後面的主要動詞用原形。", "location": "把原句的「brought」圈起來，與同一位置應有的「bring」比較。不要把沒有錯的部分一併重寫。", "reason": "過去或單數資訊已由 did/does 表示，主要動詞不能再變成 went/plays。", "tip": "Does he go? Did they go? 不能重複標記。", "course": "B 不帶 to 的動詞原形；細項 19。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (162,'{"number": 162, "sentence": "We are going to decorate the hall this afternoon.", "mark": "tick", "topic": "be going to 的完整結構", "wrong": "", "fix": "", "correct_sentence": "We are going to decorate the hall this afternoon.", "hint": "留意已有打算或看得到的跡象。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "am/is/are going to + 原形；不要漏掉 be，也不要寫 going to + -ing。", "tip": "I am / she is / they are going to do。", "course": "G 前置知識與 if 條件句；細項 66。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (163,'{"number": 163, "sentence": "I forgot my umbrella, so I got wet.", "mark": "tick", "topic": "so + 結果子句", "wrong": "", "fix": "", "correct_sentence": "I forgot my umbrella, so I got wet.", "hint": "句子前半段說原因，後半段描述實際結果。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "so 可連接兩個完整子句，表示「所以」：It rained, so we stayed inside。", "tip": "先圈出原因，再圈出結果；so 後應有完整句子。", "course": "F So / so that / so as to；細項 51。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (164,'{"number": 164, "sentence": "The science club meets every Friday.", "mark": "tick", "topic": "第三身單數加 -s", "wrong": "", "fix": "", "correct_sentence": "The science club meets every Friday.", "hint": "找真正的主語：he、she、it 或單數名詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般現在式中，第三身單數動詞要用 -s；主語是複數時則不要亂加。", "tip": "用 he/she/it 代替主語，試讀一次動詞。", "course": "A 現在式與現在進行式；細項 03。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (165,'{"number": 165, "sentence": "We left the gate open so that the delivery team could enter.", "mark": "tick", "topic": "so that 後有主語與動詞", "wrong": "", "fix": "", "correct_sentence": "We left the gate open so that the delivery team could enter.", "hint": "so that 表示「為了讓……」，後面通常有完整的主語和謂語。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "so that + 主語 + 動詞／情態動詞，不等於 so as to + 原形。", "tip": "檢查 so that 後，有沒有「誰做甚麼」。", "course": "F So / so that / so as to；細項 53。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (166,'{"number": 166, "sentence": "He would rather taking the MTR than drive.", "mark": "cross", "topic": "would rather + 動詞原形", "wrong": "rather taking", "fix": "rather take", "correct_sentence": "He would rather take the MTR than drive.", "hint": "見到 would rather，就要檢查後面的第一個動詞。", "location": "把原句的「rather taking」圈起來，與同一位置應有的「rather take」比較。不要把沒有錯的部分一併重寫。", "reason": "表示「寧願」時通常用 would rather + 原形，不接 to：rather stay。", "tip": "記 would rather stay than go。", "course": "B 不帶 to 的動詞原形；細項 23。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (167,'{"number": 167, "sentence": "If I skip breakfast, I feel hungry before lunch.", "mark": "tick", "topic": "Zero conditional：事實與規律", "wrong": "", "fix": "", "correct_sentence": "If I skip breakfast, I feel hungry before lunch.", "hint": "if 子句與主句都描述反覆成立的事實或規律。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "零類條件句常用 if + 現在式，主句也用現在式：If you heat ice, it melts。", "tip": "先想「每次這樣就會那樣」是否屬規律。", "course": "G 前置知識與 if 條件句；細項 70。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (168,'{"number": 168, "sentence": "The club suggested to hold a second meeting.", "mark": "cross", "topic": "enjoy / avoid / suggest 後用 -ing", "wrong": "suggested to hold", "fix": "suggested holding", "correct_sentence": "The club suggested holding a second meeting.", "hint": "找到 enjoy、avoid、suggest，檢查下一個動詞形式。", "location": "把原句的「suggested to hold」圈起來，與同一位置應有的「suggested holding」比較。不要把沒有錯的部分一併重寫。", "reason": "這類動詞常接動名詞：enjoy reading、avoid making、suggest working。", "tip": "見到三個動詞，先試用 -ing，不要直接加 to。", "course": "G 前置知識與 if 條件句；細項 68。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (169,'{"number": 169, "sentence": "Does Lucy has to submit the form today?", "mark": "cross", "topic": "have to 問句用 do/does", "wrong": "Does Lucy has", "fix": "Does Lucy have", "correct_sentence": "Does Lucy have to submit the form today?", "hint": "句子在問某人是否必須做某事。", "location": "把原句的「Does Lucy has」圈起來，與同一位置應有的「Does Lucy have」比較。不要把沒有錯的部分一併重寫。", "reason": "一般現在式問句用 Do/Does + 主語 + have to + 原形；不是 Does she has to。", "tip": "Does he have to go? 一口氣檢查兩個地方。", "course": "E Must / have to / need to；細項 50。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (170,'{"number": 170, "sentence": "We do not have to wear uniforms on the charity dress day.", "mark": "tick", "topic": "do not have to = 不必", "wrong": "", "fix": "", "correct_sentence": "We do not have to wear uniforms on the charity dress day.", "hint": "句子在說「可以選擇」，不是「禁止」。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "do not have to = 沒有必要做；must not = 不准做。兩者意思完全不同。", "tip": "問：「可不可以做？」可以但不必 = don’t have to。", "course": "E Must / have to / need to；細項 44。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (171,'{"number": 171, "sentence": "By the time the guests came, the team has prepared the hall.", "mark": "cross", "topic": "過去完成式：比另一過去事件更早", "wrong": "has prepared", "fix": "had prepared", "correct_sentence": "By the time the guests came, the team had prepared the hall.", "hint": "留意 by the time + 過去動詞；有兩件在過去發生的事。", "location": "把原句的「has prepared」圈起來，與同一位置應有的「had prepared」比較。不要把沒有錯的部分一併重寫。", "reason": "過去完成式 had + 過去分詞，用來說明一件事在另一個過去點前已完成。", "tip": "先發生 had done；後發生 did。", "course": "G 前置知識與 if 條件句；細項 62。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (172,'{"number": 172, "sentence": "Do this machine work properly?", "mark": "cross", "topic": "現在式問句：do / does", "wrong": "Do", "fix": "Does", "correct_sentence": "Does this machine work properly?", "hint": "看句子是不是一般現在式的疑問句，並找 do/does 後的主語。", "location": "把原句的「Do」圈起來，與同一位置應有的「Does」比較。不要把沒有錯的部分一併重寫。", "reason": "一般動詞的現在式問句通常要 do/does；does 後面的主要動詞回到原形。", "tip": "記住：Does she PLAY? 不是 Does she PLAYS?", "course": "A 現在式與現在進行式；細項 05。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (173,'{"number": 173, "sentence": "Maya usually walk to school with her sister.", "mark": "cross", "topic": "現在習慣：頻率副詞", "wrong": "walk", "fix": "walks", "correct_sentence": "Maya usually walks to school with her sister.", "hint": "留意 usually、often、every morning 等字；它們在說日常習慣。", "location": "把原句的「walk」圈起來，與同一位置應有的「walks」比較。不要把沒有錯的部分一併重寫。", "reason": "習慣是反覆發生的事，通常用一般現在式，不用過去式或為了「正在」而硬加 -ing。", "tip": "看到頻率字，先問「是天天如此，還是此刻一次？」", "course": "A 現在式與現在進行式；細項 01。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (174,'{"number": 174, "sentence": "If we lived nearer, we will walk to school.", "mark": "cross", "topic": "Second conditional：假設／不太可能", "wrong": "we will walk", "fix": "we would walk", "correct_sentence": "If we lived nearer, we would walk to school.", "hint": "if 子句在提出假設，主句用 would + 原形。", "location": "把原句的「we will walk」圈起來，與同一位置應有的「we would walk」比較。不要把沒有錯的部分一併重寫。", "reason": "第二類常用 if + 過去式，would + 原形；這個過去式不一定表示過去時間。", "tip": "If I had more time, I would read more。", "course": "G 前置知識與 if 條件句；細項 72。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (175,'{"number": 175, "sentence": "Did you notice unusual anything in the experiment?", "mark": "cross", "topic": "形容詞放在 -thing/-one 後", "wrong": "unusual anything", "fix": "anything unusual", "correct_sentence": "Did you notice anything unusual in the experiment?", "hint": "檢查 something useful、anyone reliable 這類不定代名詞。", "location": "把原句的「unusual anything」圈起來，與同一位置應有的「anything unusual」比較。不要把沒有錯的部分一併重寫。", "reason": "修飾不定代名詞的形容詞通常放在後面：something interesting，而不是 interesting something。", "tip": "背一組：anything new、someone kind。", "course": "C 不定代名詞；細項 34。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (176,'{"number": 176, "sentence": "If the sensor detects smoke, the alarm sound.", "mark": "cross", "topic": "Zero conditional：事實與規律", "wrong": "sound", "fix": "sounds", "correct_sentence": "If the sensor detects smoke, the alarm sounds.", "hint": "if 子句與主句都描述反覆成立的事實或規律。", "location": "把原句的「sound」圈起來，與同一位置應有的「sounds」比較。不要把沒有錯的部分一併重寫。", "reason": "零類條件句常用 if + 現在式，主句也用現在式：If you heat ice, it melts。", "tip": "先想「每次這樣就會那樣」是否屬規律。", "course": "G 前置知識與 if 條件句；細項 70。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (177,'{"number": 177, "sentence": "Something are blocking the emergency exit.", "mark": "cross", "topic": "肯定句的 somebody / something", "wrong": "are blocking", "fix": "is blocking", "correct_sentence": "Something is blocking the emergency exit.", "hint": "句子在肯定地說有某個人或某件東西。", "location": "把原句的「are blocking」圈起來，與同一位置應有的「is blocking」比較。不要把沒有錯的部分一併重寫。", "reason": "肯定句介紹某人或某事常用 somebody/something；any- 也可能有「任何」意思，須靠語境，不可機械地當錯。", "tip": "想「有人／某件事」時，先考慮 some-。", "course": "C 不定代名詞；細項 32。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (178,'{"number": 178, "sentence": "Did you finish the reading task yesterday?", "mark": "tick", "topic": "do / does / did 後動詞原形", "wrong": "", "fix": "", "correct_sentence": "Did you finish the reading task yesterday?", "hint": "見到 do、does 或 did 是助動詞，後面的主要動詞用原形。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "過去或單數資訊已由 did/does 表示，主要動詞不能再變成 went/plays。", "tip": "Does he go? Did they go? 不能重複標記。", "course": "B 不帶 to 的動詞原形；細項 19。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (179,'{"number": 179, "sentence": "Amy would rather to read than watch television.", "mark": "cross", "topic": "would rather + 動詞原形", "wrong": "rather to read", "fix": "rather read", "correct_sentence": "Amy would rather read than watch television.", "hint": "見到 would rather，就要檢查後面的第一個動詞。", "location": "把原句的「rather to read」圈起來，與同一位置應有的「rather read」比較。不要把沒有錯的部分一併重寫。", "reason": "表示「寧願」時通常用 would rather + 原形，不接 to：rather stay。", "tip": "記 would rather stay than go。", "course": "B 不帶 to 的動詞原形；細項 23。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (180,'{"number": 180, "sentence": "If you heat ice, it melts.", "mark": "tick", "topic": "Zero conditional：事實與規律", "wrong": "", "fix": "", "correct_sentence": "If you heat ice, it melts.", "hint": "if 子句與主句都描述反覆成立的事實或規律。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "零類條件句常用 if + 現在式，主句也用現在式：If you heat ice, it melts。", "tip": "先想「每次這樣就會那樣」是否屬規律。", "course": "G 前置知識與 if 條件句；細項 70。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (181,'{"number": 181, "sentence": "Our flight depart at six tomorrow.", "mark": "cross", "topic": "時間表：將來活動可用現在式", "wrong": "depart", "fix": "departs", "correct_sentence": "Our flight departs at six tomorrow.", "hint": "句子談巴士、課堂、電影等固定時間表。", "location": "把原句的「depart」圈起來，與同一位置應有的「departs」比較。不要把沒有錯的部分一併重寫。", "reason": "已訂好的時間表即使在未來，也可以用一般現在式：The train leaves at six。", "tip": "看「固定時間表」而不只是看到 tomorrow 就改 will。", "course": "A 現在式與現在進行式；細項 08。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (182,'{"number": 182, "sentence": "She wants to learn how to code.", "mark": "tick", "topic": "want / decide / hope 後用 to + 原形", "wrong": "", "fix": "", "correct_sentence": "She wants to learn how to code.", "hint": "找到 want、decide 或 hope 這些表達打算的動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "常用 want to、decide to、hope to + 原形；與 enjoy/suggest + -ing 不同。", "tip": "把動詞與後面的結構整組記住。", "course": "G 前置知識與 if 條件句；細項 69。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (183,'{"number": 183, "sentence": "Please avoid making unnecessary noise in the library.", "mark": "tick", "topic": "enjoy / avoid / suggest 後用 -ing", "wrong": "", "fix": "", "correct_sentence": "Please avoid making unnecessary noise in the library.", "hint": "找到 enjoy、avoid、suggest，檢查下一個動詞形式。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "這類動詞常接動名詞：enjoy reading、avoid making、suggest working。", "tip": "見到三個動詞，先試用 -ing，不要直接加 to。", "course": "G 前置知識與 if 條件句；細項 68。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (184,'{"number": 184, "sentence": "She does not have to stay after school today.", "mark": "tick", "topic": "does not have to + 原形", "wrong": "", "fix": "", "correct_sentence": "She does not have to stay after school today.", "hint": "主語是 he/she/it，而句子要說「不必」。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "does not have to + 原形；前面有 does 時，不能說 doesn’t has to。", "tip": "does 已經負責第三身單數，have 不再變 has。", "course": "E Must / have to / need to；細項 45。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (185,'{"number": 185, "sentence": "She does not need to come early for the optional meeting.", "mark": "tick", "topic": "do not need to = 無須", "wrong": "", "fix": "", "correct_sentence": "She does not need to come early for the optional meeting.", "hint": "句子要說一件事不是必需的，並不代表禁止。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "do/does not need to + 原形，表示不用做；與 must not（禁止）分開。", "tip": "「不用」≠「不准」。", "course": "E Must / have to / need to；細項 47。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (186,'{"number": 186, "sentence": "She has studied Japanese since Primary Six.", "mark": "tick", "topic": "for / since 的時間用法", "wrong": "", "fix": "", "correct_sentence": "She has studied Japanese since Primary Six.", "hint": "找出時間是「一段長度」還是「開始那個點」。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "for + 一段時間（for three years）；since + 起點（since 2023）。", "tip": "for = 多久；since = 從何時開始。", "course": "G 前置知識與 if 條件句；細項 64。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (187,'{"number": 187, "sentence": "Everybody need to wear a visitor badge.", "mark": "cross", "topic": "everyone / everybody 用單數動詞", "wrong": "need", "fix": "needs", "correct_sentence": "Everybody needs to wear a visitor badge.", "hint": "留意 everyone、everybody 雖然指很多人，文法上當單數。", "location": "把原句的「need」圈起來，與同一位置應有的「needs」比較。不要把沒有錯的部分一併重寫。", "reason": "everyone/everybody + is/has/動詞-s；不能因為意思是「所有人」而用 are。", "tip": "把 everyone 當作 he/she 來試配動詞。", "course": "C 不定代名詞；細項 26。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (188,'{"number": 188, "sentence": "By the time the match began, we had found our seats.", "mark": "tick", "topic": "過去完成式：比另一過去事件更早", "wrong": "", "fix": "", "correct_sentence": "By the time the match began, we had found our seats.", "hint": "留意 by the time + 過去動詞；有兩件在過去發生的事。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "過去完成式 had + 過去分詞，用來說明一件事在另一個過去點前已完成。", "tip": "先發生 had done；後發生 did。", "course": "G 前置知識與 if 條件句；細項 62。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (189,'{"number": 189, "sentence": "She had better brought an umbrella tomorrow.", "mark": "cross", "topic": "had better + 動詞原形", "wrong": "had better brought", "fix": "had better bring", "correct_sentence": "She had better bring an umbrella tomorrow.", "hint": "留意 had better 這一組提出建議的字。", "location": "把原句的「had better brought」圈起來，與同一位置應有的「had better bring」比較。不要把沒有錯的部分一併重寫。", "reason": "had better 後直接接原形：had better leave；雖有 had，不表示動詞要用過去式。", "tip": "had better 不加 to。", "course": "B 不帶 to 的動詞原形；細項 22。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (190,'{"number": 190, "sentence": "We look forward to meeting the exchange students.", "mark": "tick", "topic": "介詞後用 -ing（動名詞）", "wrong": "", "fix": "", "correct_sentence": "We look forward to meeting the exchange students.", "hint": "留意 look forward to、interested in、good at 等搭配。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "介詞後接名詞或動名詞 -ing：interested in reading；其中 look forward to 的 to 是介詞。", "tip": "先判斷 to 是介詞還是不定式標誌。", "course": "G 前置知識與 if 條件句；細項 67。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (191,'{"number": 191, "sentence": "Her kind words made me feel better.", "mark": "tick", "topic": "主動 make + 人 + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "Her kind words made me feel better.", "hint": "句子的意思是「令某人做某事」，而 make 是主動式。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "make/made someone do something；主動使役用原形，不用 to do。", "tip": "made us clean；不要 made us to clean。", "course": "B 不帶 to 的動詞原形；細項 21。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (192,'{"number": 192, "sentence": "Unless that you revise regularly, you may forget the new words.", "mark": "cross", "topic": "unless = if ... not", "wrong": "Unless that you", "fix": "Unless you", "correct_sentence": "Unless you revise regularly, you may forget the new words.", "hint": "留意 unless 這個字：它本身已帶「除非／如果不」的意思。", "location": "把原句的「Unless that you」圈起來，與同一位置應有的「Unless you」比較。不要把沒有錯的部分一併重寫。", "reason": "Unless you hurry, you will miss the train = If you do not hurry ...；不要把 unless 當 because。", "tip": "用 if ... not 改寫一次，看兩句意思是否相同。", "course": "D Unless 條件句；細項 35。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (193,'{"number": 193, "sentence": "We decided meeting after the final lesson.", "mark": "cross", "topic": "want / decide / hope 後用 to + 原形", "wrong": "decided meeting", "fix": "decided to meet", "correct_sentence": "We decided to meet after the final lesson.", "hint": "找到 want、decide 或 hope 這些表達打算的動詞。", "location": "把原句的「decided meeting」圈起來，與同一位置應有的「decided to meet」比較。不要把沒有錯的部分一併重寫。", "reason": "常用 want to、decide to、hope to + 原形；與 enjoy/suggest + -ing 不同。", "tip": "把動詞與後面的結構整組記住。", "course": "G 前置知識與 if 條件句；細項 69。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (194,'{"number": 194, "sentence": "The printer does not works on weekends.", "mark": "cross", "topic": "現在式否定：do not / does not", "wrong": "does not works", "fix": "does not work", "correct_sentence": "The printer does not work on weekends.", "hint": "找 not 前面的助動詞，留意主語單複數。", "location": "把原句的「does not works」圈起來，與同一位置應有的「does not work」比較。不要把沒有錯的部分一併重寫。", "reason": "he/she/it 用 does not + 原形；I/you/we/they 用 do not + 原形。", "tip": "把「doesn''t + 原形」當成一組。", "course": "A 現在式與現在進行式；細項 06。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (195,'{"number": 195, "sentence": "The guide spoke louder so that everyone could hear.", "mark": "tick", "topic": "so that + could：過去目的", "wrong": "", "fix": "", "correct_sentence": "The guide spoke louder so that everyone could hear.", "hint": "主句說的是已發生的過去行動，目的是讓當時某人能做到某事。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "常用 so that + 主語 + could + 原形；could 後不能加 to。", "tip": "先確認主句時間，再配 can/could。", "course": "F So / so that / so as to；細項 55。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (196,'{"number": 196, "sentence": "You must not pay for this free exhibition.", "mark": "cross", "topic": "do not have to = 不必", "wrong": "must not", "fix": "do not have to", "correct_sentence": "You do not have to pay for this free exhibition.", "hint": "句子在說「可以選擇」，不是「禁止」。", "location": "把原句的「must not」圈起來，與同一位置應有的「do not have to」比較。不要把沒有錯的部分一併重寫。", "reason": "do not have to = 沒有必要做；must not = 不准做。兩者意思完全不同。", "tip": "問：「可不可以做？」可以但不必 = don’t have to。", "course": "E Must / have to / need to；細項 44。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (197,'{"number": 197, "sentence": "We will call the teacher if the projector stops working.", "mark": "tick", "topic": "First conditional：真實可能的將來", "wrong": "", "fix": "", "correct_sentence": "We will call the teacher if the projector stops working.", "hint": "if 子句說將來有可能發生的情況，主句有 will。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "常用 if + 現在式，will + 原形；if 子句一般不直接用 will 表普通未來。", "tip": "If it rains, we will stay inside。", "course": "G 前置知識與 if 條件句；細項 71。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (198,'{"number": 198, "sentence": "She is knowing the answer to this question.", "mark": "cross", "topic": "狀態動詞：know / believe / understand", "wrong": "is knowing", "fix": "knows", "correct_sentence": "She knows the answer to this question.", "hint": "句子描述知道、相信、明白的狀態，不是正在進行的動作。", "location": "把原句的「is knowing」圈起來，與同一位置應有的「knows」比較。不要把沒有錯的部分一併重寫。", "reason": "know、believe、understand 通常不用現在進行式；I know 而非 I am knowing。", "tip": "見到「心裡的狀態」，先別急着加 -ing。", "course": "A 現在式與現在進行式；細項 15。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (199,'{"number": 199, "sentence": "You do not have to bring lunch; the school provides it.", "mark": "tick", "topic": "do not have to = 不必", "wrong": "", "fix": "", "correct_sentence": "You do not have to bring lunch; the school provides it.", "hint": "句子在說「可以選擇」，不是「禁止」。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "do not have to = 沒有必要做；must not = 不准做。兩者意思完全不同。", "tip": "問：「可不可以做？」可以但不必 = don’t have to。", "course": "E Must / have to / need to；細項 44。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (200,'{"number": 200, "sentence": "Unless you not lock the door, the room will not be secure.", "mark": "cross", "topic": "unless 的邏輯：不要誤加 not", "wrong": "you not lock", "fix": "you lock", "correct_sentence": "Unless you lock the door, the room will not be secure.", "hint": "看 unless 後面的否定字會不會把原意倒轉。", "location": "把原句的「you not lock」圈起來，與同一位置應有的「you lock」比較。不要把沒有錯的部分一併重寫。", "reason": "unless 已含「如果不」；若再加 not，整句條件會變成另一種意思，不是每次都錯，必須用上下文判斷。", "tip": "先把 unless 改寫成 if not，再檢查有沒有兩個「不」。", "course": "D Unless 條件句；細項 37。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (201,'{"number": 201, "sentence": "You should check your answers before handing in the paper.", "mark": "tick", "topic": "should / may / might 後原形", "wrong": "", "fix": "", "correct_sentence": "You should check your answers before handing in the paper.", "hint": "找到 should、may 或 might；它們都屬情態動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "should/may/might 後面直接接原形，不要多加 to 或 -ing。", "tip": "試用 should go、may leave、might rain 記憶。", "course": "B 不帶 to 的動詞原形；細項 18。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (202,'{"number": 202, "sentence": "More students are joining the recycling programme these days.", "mark": "tick", "topic": "正在改變的情況及趨勢", "wrong": "", "fix": "", "correct_sentence": "More students are joining the recycling programme these days.", "hint": "留意 gradually、these days、more and more 等表示變化中的字。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "強調現正發展的趨勢時，通常用現在進行式；它不同於永遠不變的事實。", "tip": "想像有一條上升／下降中的線：is increasing。", "course": "A 現在式與現在進行式；細項 13。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (203,'{"number": 203, "sentence": "We waited until the rain stopped before going outside.", "mark": "tick", "topic": "unless 與 until 不同", "wrong": "", "fix": "", "correct_sentence": "We waited until the rain stopped before going outside.", "hint": "中文的「直到」和「除非」不同；看句子是否表達時間還是條件。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "until = 直到某時；unless = 除非某條件。They waited until the rain stopped 不是 unless。", "tip": "如果可以問「等到幾時？」就檢查 until。", "course": "D Unless 條件句；細項 38。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (204,'{"number": 204, "sentence": "The team met after school so as to finished the model.", "mark": "cross", "topic": "so as to + 動詞原形", "wrong": "so as to finished", "fix": "so as to finish", "correct_sentence": "The team met after school so as to finish the model.", "hint": "看 so as to 後面的動詞形式。", "location": "把原句的「so as to finished」圈起來，與同一位置應有的「so as to finish」比較。不要把沒有錯的部分一併重寫。", "reason": "so as to 後直接接原形，表示「為了」：so as to save time。", "tip": "so as to finish，不是 so as to finishing。", "course": "F So / so that / so as to；細項 56。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (205,'{"number": 205, "sentence": "I saved my pocket money so as to buy a new dictionary.", "mark": "tick", "topic": "so as to 的動作主語要一致", "wrong": "", "fix": "", "correct_sentence": "I saved my pocket money so as to buy a new dictionary.", "hint": "比較主句誰做動作，以及 so as to 後誰想達到目的。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "so as to 的未明說主語通常就是主句主語；若目的是讓另一個人做事，改用 so that + 那個人 + can/could。", "tip": "問兩次「是誰做？」；不同人便考慮 so that。", "course": "F So / so that / so as to；細項 58。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (206,'{"number": 206, "sentence": "We are arranging the display boards right now.", "mark": "tick", "topic": "進行式：am/is/are + -ing", "wrong": "", "fix": "", "correct_sentence": "We are arranging the display boards right now.", "hint": "留意 right now、at the moment；找主語、be 和 -ing 是否齊全。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "現在進行式有兩部分：am/is/are + 動詞-ing；不可只剩 -ing。", "tip": "三步檢查：「誰？」→「am/is/are？」→「-ing？」", "course": "A 現在式與現在進行式；細項 09。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (207,'{"number": 207, "sentence": "The class needs choose a group leader.", "mark": "cross", "topic": "need to + 原形", "wrong": "needs choose", "fix": "needs to choose", "correct_sentence": "The class needs to choose a group leader.", "hint": "句子在說有一件需要完成的事情。", "location": "把原句的「needs choose」圈起來，與同一位置應有的「needs to choose」比較。不要把沒有錯的部分一併重寫。", "reason": "一般動詞 need 接 to-infinitive：need to finish；不要接 need finish（這裡不是情態用法）。", "tip": "I need to + 動詞原形。", "course": "E Must / have to / need to；細項 46。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (208,'{"number": 208, "sentence": "Unless that she asks for help, the teacher will not know she is struggling.", "mark": "cross", "topic": "unless = if ... not", "wrong": "Unless that she", "fix": "Unless she", "correct_sentence": "Unless she asks for help, the teacher will not know she is struggling.", "hint": "留意 unless 這個字：它本身已帶「除非／如果不」的意思。", "location": "把原句的「Unless that she」圈起來，與同一位置應有的「Unless she」比較。不要把沒有錯的部分一併重寫。", "reason": "Unless you hurry, you will miss the train = If you do not hurry ...；不要把 unless 當 because。", "tip": "用 if ... not 改寫一次，看兩句意思是否相同。", "course": "D Unless 條件句；細項 35。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (209,'{"number": 209, "sentence": "She checked twice so as not making a careless mistake.", "mark": "cross", "topic": "so as not to + 動詞原形", "wrong": "so as not making", "fix": "so as not to make", "correct_sentence": "She checked twice so as not to make a careless mistake.", "hint": "句子表示「為了避免某事」，注意 not 的位置。", "location": "把原句的「so as not making」圈起來，與同一位置應有的「so as not to make」比較。不要把沒有錯的部分一併重寫。", "reason": "正確順序是 so as not to + 原形；not 要放在 to 前。", "tip": "整組背起來：so as not to disturb。", "course": "F So / so that / so as to；細項 57。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (210,'{"number": 210, "sentence": "The students preparing a short performance.", "mark": "cross", "topic": "進行式：am/is/are + -ing", "wrong": "preparing", "fix": "are preparing", "correct_sentence": "The students are preparing a short performance.", "hint": "留意 right now、at the moment；找主語、be 和 -ing 是否齊全。", "location": "把原句的「preparing」圈起來，與同一位置應有的「are preparing」比較。不要把沒有錯的部分一併重寫。", "reason": "現在進行式有兩部分：am/is/are + 動詞-ing；不可只剩 -ing。", "tip": "三步檢查：「誰？」→「am/is/are？」→「-ing？」", "course": "A 現在式與現在進行式；細項 09。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (211,'{"number": 211, "sentence": "Have anyone seen the missing calculator?", "mark": "cross", "topic": "問句的 anybody / anything", "wrong": "Have anyone", "fix": "Has anyone", "correct_sentence": "Has anyone seen the missing calculator?", "hint": "普通問句在詢問是否有人／有東西，答案未知。", "location": "把原句的「Have anyone」圈起來，與同一位置應有的「Has anyone」比較。不要把沒有錯的部分一併重寫。", "reason": "一般中性問句多用 anyone/anybody/anything；但邀請或期待肯定回應的問句可以用 some-，不要一概硬改。", "tip": "先分清「中性查詢」還是「禮貌邀請」。", "course": "C 不定代名詞；細項 31。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (212,'{"number": 212, "sentence": "Good sleep helps students concentrate.", "mark": "tick", "topic": "一般事實及科學真理", "wrong": "", "fix": "", "correct_sentence": "Good sleep helps students concentrate.", "hint": "句子在講普遍成立的事實，而不是某個人此刻正在做的事。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "科學事實、定義、自然規律常用一般現在式；沒有理由就不要改成現在進行式。", "tip": "先想：「這句話明天也通常成立嗎？」成立就傾向用現在式。", "course": "A 現在式與現在進行式；細項 02。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (213,'{"number": 213, "sentence": "I understand the instructions for the project.", "mark": "tick", "topic": "狀態動詞：know / believe / understand", "wrong": "", "fix": "", "correct_sentence": "I understand the instructions for the project.", "hint": "句子描述知道、相信、明白的狀態，不是正在進行的動作。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "know、believe、understand 通常不用現在進行式；I know 而非 I am knowing。", "tip": "見到「心裡的狀態」，先別急着加 -ing。", "course": "A 現在式與現在進行式；細項 15。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (214,'{"number": 214, "sentence": "The teacher slowed down so that the younger pupils could understand.", "mark": "tick", "topic": "so that + could：過去目的", "wrong": "", "fix": "", "correct_sentence": "The teacher slowed down so that the younger pupils could understand.", "hint": "主句說的是已發生的過去行動，目的是讓當時某人能做到某事。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "常用 so that + 主語 + could + 原形；could 後不能加 to。", "tip": "先確認主句時間，再配 can/could。", "course": "F So / so that / so as to；細項 55。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (215,'{"number": 215, "sentence": "I have two bags: one is black and the other is green.", "mark": "tick", "topic": "none of / another / the other", "wrong": "", "fix": "", "correct_sentence": "I have two bags: one is black and the other is green.", "hint": "看 none 後有沒有 of；再看 another 後的單數名詞及已經提過的兩件物件。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "none of + 指定的一群人／東西；another + 單數可數名詞表示另外一個；若明確只有兩個，第二個通常叫 the other。", "tip": "背短語：none of the books；another chair；one ... the other。", "course": "C 不定代名詞；細項 40。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (216,'{"number": 216, "sentence": "She wants to share interesting something with the class.", "mark": "cross", "topic": "形容詞放在 -thing/-one 後", "wrong": "interesting something", "fix": "something interesting", "correct_sentence": "She wants to share something interesting with the class.", "hint": "檢查 something useful、anyone reliable 這類不定代名詞。", "location": "把原句的「interesting something」圈起來，與同一位置應有的「something interesting」比較。不要把沒有錯的部分一併重寫。", "reason": "修飾不定代名詞的形容詞通常放在後面：something interesting，而不是 interesting something。", "tip": "背一組：anything new、someone kind。", "course": "C 不定代名詞；細項 34。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (217,'{"number": 217, "sentence": "While Dad was cooked dinner, the doorbell rang.", "mark": "cross", "topic": "過去進行式：背景 + 突發事件", "wrong": "was cooked", "fix": "was cooking", "correct_sentence": "While Dad was cooking dinner, the doorbell rang.", "hint": "一件事發生時，另一件事情正在進行。", "location": "把原句的「was cooked」圈起來，與同一位置應有的「was cooking」比較。不要把沒有錯的部分一併重寫。", "reason": "長一點的背景動作用 was/were + -ing；較短的插入事件用一般過去式。", "tip": "一條時間線：was reading → phone rang。", "course": "G 前置知識與 if 條件句；細項 61。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (218,'{"number": 218, "sentence": "The teacher needs someone reliable to collect the forms.", "mark": "tick", "topic": "形容詞放在 -thing/-one 後", "wrong": "", "fix": "", "correct_sentence": "The teacher needs someone reliable to collect the forms.", "hint": "檢查 something useful、anyone reliable 這類不定代名詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "修飾不定代名詞的形容詞通常放在後面：something interesting，而不是 interesting something。", "tip": "背一組：anything new、someone kind。", "course": "C 不定代名詞；細項 34。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (219,'{"number": 219, "sentence": "Our team carrys its own water bottles.", "mark": "cross", "topic": "第三身 -es 與 -ies 拼字", "wrong": "carrys", "fix": "carries", "correct_sentence": "Our team carries its own water bottles.", "hint": "主語是單數；注意動詞結尾 ch、sh、o 或 consonant + y。", "location": "把原句的「carrys」圈起來，與同一位置應有的「carries」比較。不要把沒有錯的部分一併重寫。", "reason": "watch → watches；study → studies。不是任何動詞都只直接加 -s。", "tip": "先看字尾，再決定加 -s、-es 或改 y 為 ies。", "course": "A 現在式與現在進行式；細項 04。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (220,'{"number": 220, "sentence": "We put labels on the boxes so that everyone can to find the right one.", "mark": "cross", "topic": "so that + can：現在目的", "wrong": "can to find", "fix": "can find", "correct_sentence": "We put labels on the boxes so that everyone can find the right one.", "hint": "句子在說現在／將來的目的，目標是「能夠做到」。", "location": "把原句的「can to find」圈起來，與同一位置應有的「can find」比較。不要把沒有錯的部分一併重寫。", "reason": "用 so that + 人 + can + 原形：I speak clearly so that you can hear。", "tip": "目的句中 can 後不可加 to。", "course": "F So / so that / so as to；細項 54。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (221,'{"number": 221, "sentence": "They are going to organising a food drive.", "mark": "cross", "topic": "be going to 的完整結構", "wrong": "to organising", "fix": "to organise", "correct_sentence": "They are going to organise a food drive.", "hint": "留意已有打算或看得到的跡象。", "location": "把原句的「to organising」圈起來，與同一位置應有的「to organise」比較。不要把沒有錯的部分一併重寫。", "reason": "am/is/are going to + 原形；不要漏掉 be，也不要寫 going to + -ing。", "tip": "I am / she is / they are going to do。", "course": "G 前置知識與 if 條件句；細項 66。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (222,'{"number": 222, "sentence": "Our school is becoming more environmentally friendly.", "mark": "tick", "topic": "正在改變的情況及趨勢", "wrong": "", "fix": "", "correct_sentence": "Our school is becoming more environmentally friendly.", "hint": "留意 gradually、these days、more and more 等表示變化中的字。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "強調現正發展的趨勢時，通常用現在進行式；它不同於永遠不變的事實。", "tip": "想像有一條上升／下降中的線：is increasing。", "course": "A 現在式與現在進行式；細項 13。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (223,'{"number": 223, "sentence": "The microphone stopped working, so as to the host spoke loudly.", "mark": "cross", "topic": "so + 結果子句", "wrong": "so as to the host", "fix": "so the host", "correct_sentence": "The microphone stopped working, so the host spoke loudly.", "hint": "句子前半段說原因，後半段描述實際結果。", "location": "把原句的「so as to the host」圈起來，與同一位置應有的「so the host」比較。不要把沒有錯的部分一併重寫。", "reason": "so 可連接兩個完整子句，表示「所以」：It rained, so we stayed inside。", "tip": "先圈出原因，再圈出結果；so 後應有完整句子。", "course": "F So / so that / so as to；細項 51。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (224,'{"number": 224, "sentence": "Our teacher will announce the winner on Friday.", "mark": "tick", "topic": "will + 動詞原形：未來", "wrong": "", "fix": "", "correct_sentence": "Our teacher will announce the winner on Friday.", "hint": "留意承諾、預測、即時決定，並檢查 will 後的動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "will 後直接跟動詞原形，不加 to，也不變 -s/-ed。", "tip": "will go、will help、will arrive。", "course": "G 前置知識與 if 條件句；細項 65。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (225,'{"number": 225, "sentence": "He had better apologise for the misunderstanding.", "mark": "tick", "topic": "had better + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "He had better apologise for the misunderstanding.", "hint": "留意 had better 這一組提出建議的字。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "had better 後直接接原形：had better leave；雖有 had，不表示動詞要用過去式。", "tip": "had better 不加 to。", "course": "B 不帶 to 的動詞原形；細項 22。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (226,'{"number": 226, "sentence": "The team practised hard so to improve its teamwork.", "mark": "cross", "topic": "so 表結果，不是 so to + 動詞", "wrong": "so to improve", "fix": "so as to improve", "correct_sentence": "The team practised hard so as to improve its teamwork.", "hint": "看看 so 後是不是直接跟着 to + 動詞。", "location": "把原句的「so to improve」圈起來，與同一位置應有的「so as to improve」比較。不要把沒有錯的部分一併重寫。", "reason": "so 通常連接結果子句；表示目的要用 so as to + 原形，不能隨意寫 so to。", "tip": "so + 完整句；so as to + 原形。", "course": "F So / so that / so as to；細項 52。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (227,'{"number": 227, "sentence": "I have someone important to tell you.", "mark": "cross", "topic": "人用 -one/-body；物用 -thing", "wrong": "someone", "fix": "something", "correct_sentence": "I have something important to tell you.", "hint": "留意動詞的意思：是否在找人，還是在找東西？", "location": "把原句的「someone」圈起來，與同一位置應有的「something」比較。不要把沒有錯的部分一併重寫。", "reason": "someone/anyone/nobody 說人；something/anything/nothing 說事物。", "tip": "直接問「要找的是人還是物？」", "course": "C 不定代名詞；細項 33。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (228,'{"number": 228, "sentence": "He turned off the speaker so as not waking the baby.", "mark": "cross", "topic": "so as not to + 動詞原形", "wrong": "so as not waking", "fix": "so as not to wake", "correct_sentence": "He turned off the speaker so as not to wake the baby.", "hint": "句子表示「為了避免某事」，注意 not 的位置。", "location": "把原句的「so as not waking」圈起來，與同一位置應有的「so as not to wake」比較。不要把沒有錯的部分一併重寫。", "reason": "正確順序是 so as not to + 原形；not 要放在 to 前。", "tip": "整組背起來：so as not to disturb。", "course": "F So / so that / so as to；細項 57。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (229,'{"number": 229, "sentence": "We whispered so as not to disturb the people reading.", "mark": "tick", "topic": "so as not to + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "We whispered so as not to disturb the people reading.", "hint": "句子表示「為了避免某事」，注意 not 的位置。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "正確順序是 so as not to + 原形；not 要放在 to 前。", "tip": "整組背起來：so as not to disturb。", "course": "F So / so that / so as to；細項 57。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (230,'{"number": 230, "sentence": "He is going to join the school orchestra next term.", "mark": "tick", "topic": "be going to 的完整結構", "wrong": "", "fix": "", "correct_sentence": "He is going to join the school orchestra next term.", "hint": "留意已有打算或看得到的跡象。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "am/is/are going to + 原形；不要漏掉 be，也不要寫 going to + -ing。", "tip": "I am / she is / they are going to do。", "course": "G 前置知識與 if 條件句；細項 66。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (231,'{"number": 231, "sentence": "Could you help me move this table?", "mark": "tick", "topic": "can / could 後接動詞原形", "wrong": "", "fix": "", "correct_sentence": "Could you help me move this table?", "hint": "找到 can 或 could，看看後面的動詞有沒有多加 to、-s 或 -ing。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "can/could 是情態動詞，後面直接跟原形：can swim，不是 can to swim。", "tip": "把 can、could 與下一個動詞連在一起檢查。", "course": "B 不帶 to 的動詞原形；細項 16。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (232,'{"number": 232, "sentence": "Our captain check the equipment before practice.", "mark": "cross", "topic": "第三身單數加 -s", "wrong": "check", "fix": "checks", "correct_sentence": "Our captain checks the equipment before practice.", "hint": "找真正的主語：he、she、it 或單數名詞。", "location": "把原句的「check」圈起來，與同一位置應有的「checks」比較。不要把沒有錯的部分一併重寫。", "reason": "一般現在式中，第三身單數動詞要用 -s；主語是複數時則不要亂加。", "tip": "用 he/she/it 代替主語，試讀一次動詞。", "course": "A 現在式與現在進行式；細項 03。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (233,'{"number": 233, "sentence": "She is writing a report for the school magazine.", "mark": "tick", "topic": "-ing 的拼字變化", "wrong": "", "fix": "", "correct_sentence": "She is writing a report for the school magazine.", "hint": "已確定要用進行式，再檢查動詞的 -ing 拼字。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "write → writing（去 e）；run → running（雙寫 n）；lie → lying（ie 變 y）。", "tip": "先選正確時態，再看字尾拼法。", "course": "A 現在式與現在進行式；細項 10。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (234,'{"number": 234, "sentence": "The technician goed home after the demonstration.", "mark": "cross", "topic": "不規則過去式", "wrong": "goed", "fix": "went", "correct_sentence": "The technician went home after the demonstration.", "hint": "句子已有明確過去時間；找動詞的過去式是否拼對。", "location": "把原句的「goed」圈起來，與同一位置應有的「went」比較。不要把沒有錯的部分一併重寫。", "reason": "有些動詞不直接加 -ed，例如 strike → struck、go → went、bring → brought。", "tip": "常錯的動詞三態要逐個背，不能一律加 -ed。", "course": "G 前置知識與 if 條件句；細項 60。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (235,'{"number": 235, "sentence": "Each of the pupils received a certificate.", "mark": "tick", "topic": "each / either / neither 的單數用法", "wrong": "", "fix": "", "correct_sentence": "Each of the pupils received a certificate.", "hint": "先找 each、either、neither，看看後面是否有單數名詞，或 of + 複數名詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "each/either/neither 指「每一個／兩者之一／兩者皆非」。直接接可數名詞時通常接單數：neither option；如果後接 of，則用 either of the two options。", "tip": "先判斷是否有 of；沒有 of 時通常是 each student / either route / neither answer。", "course": "C 不定代名詞；細項 39。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (236,'{"number": 236, "sentence": "Does your father drives to work?", "mark": "cross", "topic": "do / does / did 後動詞原形", "wrong": "drives", "fix": "drive", "correct_sentence": "Does your father drive to work?", "hint": "見到 do、does 或 did 是助動詞，後面的主要動詞用原形。", "location": "把原句的「drives」圈起來，與同一位置應有的「drive」比較。不要把沒有錯的部分一併重寫。", "reason": "過去或單數資訊已由 did/does 表示，主要動詞不能再變成 went/plays。", "tip": "Does he go? Did they go? 不能重複標記。", "course": "B 不帶 to 的動詞原形；細項 19。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (237,'{"number": 237, "sentence": "You must return the borrowed books on time.", "mark": "tick", "topic": "must + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "You must return the borrowed books on time.", "hint": "must 表示強烈的責任、要求或必要。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "must + 原形；不接 to，不因主語單數而變 musts。", "tip": "must 的下一個動詞保持原形。", "course": "E Must / have to / need to；細項 41。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (238,'{"number": 238, "sentence": "No one have collected the parcel yet.", "mark": "cross", "topic": "nobody / no one + 單數動詞", "wrong": "have", "fix": "has", "correct_sentence": "No one has collected the parcel yet.", "hint": "句子主語是 nobody / no one。", "location": "把原句的「have」圈起來，與同一位置應有的「has」比較。不要把沒有錯的部分一併重寫。", "reason": "nobody/no one 雖然表示沒有人，仍用單數動詞：Nobody knows。", "tip": "不要見到「沒有人」就誤用複數動詞。", "course": "C 不定代名詞；細項 28。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (239,'{"number": 239, "sentence": "We would rather walk than wait for another bus.", "mark": "tick", "topic": "would rather + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "We would rather walk than wait for another bus.", "hint": "見到 would rather，就要檢查後面的第一個動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "表示「寧願」時通常用 would rather + 原形，不接 to：rather stay。", "tip": "記 would rather stay than go。", "course": "B 不帶 to 的動詞原形；細項 23。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (240,'{"number": 240, "sentence": "She has visited the museum two days ago.", "mark": "cross", "topic": "一般過去式：已完結的時間", "wrong": "has visited", "fix": "visited", "correct_sentence": "She visited the museum two days ago.", "hint": "留意 yesterday、last week、two days ago，事情已經結束。", "location": "把原句的「has visited」圈起來，與同一位置應有的「visited」比較。不要把沒有錯的部分一併重寫。", "reason": "特定過去時間發生的事件通常用一般過去式；不要混用現在完成式。", "tip": "看到 ago，先想到 did，而不是 have done。", "course": "G 前置知識與 if 條件句；細項 59。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (241,'{"number": 241, "sentence": "The hall was full, so we used the outdoor stage.", "mark": "tick", "topic": "so + 結果子句", "wrong": "", "fix": "", "correct_sentence": "The hall was full, so we used the outdoor stage.", "hint": "句子前半段說原因，後半段描述實際結果。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "so 可連接兩個完整子句，表示「所以」：It rained, so we stayed inside。", "tip": "先圈出原因，再圈出結果；so 後應有完整句子。", "course": "F So / so that / so as to；細項 51。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (242,'{"number": 242, "sentence": "The teacher made us rewrote the introduction.", "mark": "cross", "topic": "主動 make + 人 + 動詞原形", "wrong": "made us rewrote", "fix": "made us rewrite", "correct_sentence": "The teacher made us rewrite the introduction.", "hint": "句子的意思是「令某人做某事」，而 make 是主動式。", "location": "把原句的「made us rewrote」圈起來，與同一位置應有的「made us rewrite」比較。不要把沒有錯的部分一併重寫。", "reason": "make/made someone do something；主動使役用原形，不用 to do。", "tip": "made us clean；不要 made us to clean。", "course": "B 不帶 to 的動詞原形；細項 21。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (243,'{"number": 243, "sentence": "Yesterday, we had to cancel the outdoor activity.", "mark": "tick", "topic": "過去的必須：had to", "wrong": "", "fix": "", "correct_sentence": "Yesterday, we had to cancel the outdoor activity.", "hint": "事情是昨天、去年或上星期發生的強制要求。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "普通義務要談過去，常用 had to；must 不能當作一般動詞變 musted。", "tip": "現在 have to；過去 had to。", "course": "E Must / have to / need to；細項 49。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (244,'{"number": 244, "sentence": "We must remain calm during a fire drill.", "mark": "tick", "topic": "must + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "We must remain calm during a fire drill.", "hint": "must 表示強烈的責任、要求或必要。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "must + 原形；不接 to，不因主語單數而變 musts。", "tip": "must 的下一個動詞保持原形。", "course": "E Must / have to / need to；細項 41。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (245,'{"number": 245, "sentence": "I have learnt many useful skills since joining the club.", "mark": "tick", "topic": "現在完成式：至今的成果", "wrong": "", "fix": "", "correct_sentence": "I have learnt many useful skills since joining the club.", "hint": "留意 so far、up to now、since 等與現在仍有關係的時間線索。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "have/has + 過去分詞，說明以前發生而與現在有關的結果。", "tip": "「至今」想 have/has done；「昨天」想 did。", "course": "G 前置知識與 if 條件句；細項 63。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (246,'{"number": 246, "sentence": "I will help you carry the boxes after class.", "mark": "tick", "topic": "will + 動詞原形：未來", "wrong": "", "fix": "", "correct_sentence": "I will help you carry the boxes after class.", "hint": "留意承諾、預測、即時決定，並檢查 will 後的動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "will 後直接跟動詞原形，不加 to，也不變 -s/-ed。", "tip": "will go、will help、will arrive。", "course": "G 前置知識與 if 條件句；細項 65。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (247,'{"number": 247, "sentence": "You do not need to print the notes; they are online.", "mark": "tick", "topic": "do not need to = 無須", "wrong": "", "fix": "", "correct_sentence": "You do not need to print the notes; they are online.", "hint": "句子要說一件事不是必需的，並不代表禁止。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "do/does not need to + 原形，表示不用做；與 must not（禁止）分開。", "tip": "「不用」≠「不准」。", "course": "E Must / have to / need to；細項 47。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (248,'{"number": 248, "sentence": "I need to finish my homework before the rehearsal.", "mark": "tick", "topic": "need to + 原形", "wrong": "", "fix": "", "correct_sentence": "I need to finish my homework before the rehearsal.", "hint": "句子在說有一件需要完成的事情。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般動詞 need 接 to-infinitive：need to finish；不要接 need finish（這裡不是情態用法）。", "tip": "I need to + 動詞原形。", "course": "E Must / have to / need to；細項 46。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (249,'{"number": 249, "sentence": "Either of the two routes is suitable for the trip.", "mark": "tick", "topic": "each / either / neither 的單數用法", "wrong": "", "fix": "", "correct_sentence": "Either of the two routes is suitable for the trip.", "hint": "先找 each、either、neither，看看後面是否有單數名詞，或 of + 複數名詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "each/either/neither 指「每一個／兩者之一／兩者皆非」。直接接可數名詞時通常接單數：neither option；如果後接 of，則用 either of the two options。", "tip": "先判斷是否有 of；沒有 of 時通常是 each student / either route / neither answer。", "course": "C 不定代名詞；細項 39。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (250,'{"number": 250, "sentence": "Unless you not bring your ticket, you cannot enter the theatre.", "mark": "cross", "topic": "unless 的邏輯：不要誤加 not", "wrong": "you not bring", "fix": "you bring", "correct_sentence": "Unless you bring your ticket, you cannot enter the theatre.", "hint": "看 unless 後面的否定字會不會把原意倒轉。", "location": "把原句的「you not bring」圈起來，與同一位置應有的「you bring」比較。不要把沒有錯的部分一併重寫。", "reason": "unless 已含「如果不」；若再加 not，整句條件會變成另一種意思，不是每次都錯，必須用上下文判斷。", "tip": "先把 unless 改寫成 if not，再檢查有沒有兩個「不」。", "course": "D Unless 條件句；細項 37。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (251,'{"number": 251, "sentence": "He was made to apologise for his rude behaviour.", "mark": "tick", "topic": "被動 be made + to + 動詞", "wrong": "", "fix": "", "correct_sentence": "He was made to apologise for his rude behaviour.", "hint": "同樣是 make，但看誰是主語：是「被迫做」嗎？", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "主動 made us clean 不加 to；變被動時要加 to：We were made to clean。", "tip": "主動不加 to；被動 be made to do。", "course": "B 不帶 to 的動詞原形；細項 25。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (252,'{"number": 252, "sentence": "I never bring my phone into the examination room.", "mark": "tick", "topic": "現在式的 always / never / sometimes", "wrong": "", "fix": "", "correct_sentence": "I never bring my phone into the examination room.", "hint": "留意 always、never、sometimes 放在主要動詞附近。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "頻率副詞通常放在一般動詞前、be 動詞後；「never」本身已表示否定。", "tip": "問自己：是否把 never 再配 not，變成雙重否定？", "course": "A 現在式與現在進行式；細項 07。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (253,'{"number": 253, "sentence": "Our guide took us to the old harbour on Sunday.", "mark": "tick", "topic": "不規則過去式", "wrong": "", "fix": "", "correct_sentence": "Our guide took us to the old harbour on Sunday.", "hint": "句子已有明確過去時間；找動詞的過去式是否拼對。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "有些動詞不直接加 -ed，例如 strike → struck、go → went、bring → brought。", "tip": "常錯的動詞三態要逐個背，不能一律加 -ed。", "course": "G 前置知識與 if 條件句；細項 60。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (254,'{"number": 254, "sentence": "The students remained in the hall unless the bell rang.", "mark": "cross", "topic": "unless 與 until 不同", "wrong": "unless", "fix": "until", "correct_sentence": "The students remained in the hall until the bell rang.", "hint": "中文的「直到」和「除非」不同；看句子是否表達時間還是條件。", "location": "把原句的「unless」圈起來，與同一位置應有的「until」比較。不要把沒有錯的部分一併重寫。", "reason": "until = 直到某時；unless = 除非某條件。They waited until the rain stopped 不是 unless。", "tip": "如果可以問「等到幾時？」就檢查 until。", "course": "D Unless 條件句；細項 38。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (255,'{"number": 255, "sentence": "They need check the projector before the presentation.", "mark": "cross", "topic": "need to + 原形", "wrong": "need check", "fix": "need to check", "correct_sentence": "They need to check the projector before the presentation.", "hint": "句子在說有一件需要完成的事情。", "location": "把原句的「need check」圈起來，與同一位置應有的「need to check」比較。不要把沒有錯的部分一併重寫。", "reason": "一般動詞 need 接 to-infinitive：need to finish；不要接 need finish（這裡不是情態用法）。", "tip": "I need to + 動詞原形。", "course": "E Must / have to / need to；細項 46。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (256,'{"number": 256, "sentence": "He does not needs to buy a ticket because admission is free.", "mark": "cross", "topic": "do not need to = 無須", "wrong": "does not needs to", "fix": "does not need to", "correct_sentence": "He does not need to buy a ticket because admission is free.", "hint": "句子要說一件事不是必需的，並不代表禁止。", "location": "把原句的「does not needs to」圈起來，與同一位置應有的「does not need to」比較。不要把沒有錯的部分一併重寫。", "reason": "do/does not need to + 原形，表示不用做；與 must not（禁止）分開。", "tip": "「不用」≠「不准」。", "course": "E Must / have to / need to；細項 47。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (257,'{"number": 257, "sentence": "Students must not to enter the laboratory without supervision.", "mark": "cross", "topic": "must not / mustn’t = 禁止", "wrong": "must not to enter", "fix": "must not enter", "correct_sentence": "Students must not enter the laboratory without supervision.", "hint": "告示清楚說不准做一件事。", "location": "把原句的「must not to enter」圈起來，與同一位置應有的「must not enter」比較。不要把沒有錯的部分一併重寫。", "reason": "must not 表「不准」，不是「沒有必要」；必要時與 do not have to 作比較。", "tip": "看到 No entry / strictly prohibited，想 must not。", "course": "E Must / have to / need to；細項 42。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (258,'{"number": 258, "sentence": "Does the students have to bring their own tablets?", "mark": "cross", "topic": "have to 問句用 do/does", "wrong": "Does the students", "fix": "Do the students", "correct_sentence": "Do the students have to bring their own tablets?", "hint": "句子在問某人是否必須做某事。", "location": "把原句的「Does the students」圈起來，與同一位置應有的「Do the students」比較。不要把沒有錯的部分一併重寫。", "reason": "一般現在式問句用 Do/Does + 主語 + have to + 原形；不是 Does she has to。", "tip": "Does he have to go? 一口氣檢查兩個地方。", "course": "E Must / have to / need to；細項 50。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (259,'{"number": 259, "sentence": "The librarian let us use the quiet study room.", "mark": "tick", "topic": "let + 人 + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "The librarian let us use the quiet study room.", "hint": "找到 let，特別留意 let us / let me / let him 後面的動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "let someone do something，後面通常不用 to；例如 let me try。", "tip": "let + 人 + 原形，三件事排在一起。", "course": "B 不帶 to 的動詞原形；細項 20。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (260,'{"number": 260, "sentence": "Either of the two captain can lead the team.", "mark": "cross", "topic": "each / either / neither 的單數用法", "wrong": "Either of the two captain", "fix": "Either of the two captains", "correct_sentence": "Either of the two captains can lead the team.", "hint": "先找 each、either、neither，看看後面是否有單數名詞，或 of + 複數名詞。", "location": "把原句的「Either of the two captain」圈起來，與同一位置應有的「Either of the two captains」比較。不要把沒有錯的部分一併重寫。", "reason": "each/either/neither 指「每一個／兩者之一／兩者皆非」。直接接可數名詞時通常接單數：neither option；如果後接 of，則用 either of the two options。", "tip": "先判斷是否有 of；沒有 of 時通常是 each student / either route / neither answer。", "course": "C 不定代名詞；細項 39。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (261,'{"number": 261, "sentence": "The workers are not painting the wall today.", "mark": "tick", "topic": "進行式疑問句與否定句", "wrong": "", "fix": "", "correct_sentence": "The workers are not painting the wall today.", "hint": "注意問句的 am/is/are 位置，以及否定句中的 not。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "問句把 be 放主語前：Are they coming?；否定用 is not / are not + -ing。", "tip": "把陳述句 They are waiting 改成問句 Are they waiting? 試一遍。", "course": "A 現在式與現在進行式；細項 11。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (262,'{"number": 262, "sentence": "Unless it rains, the match will take place outside.", "mark": "tick", "topic": "unless = if ... not", "wrong": "", "fix": "", "correct_sentence": "Unless it rains, the match will take place outside.", "hint": "留意 unless 這個字：它本身已帶「除非／如果不」的意思。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "Unless you hurry, you will miss the train = If you do not hurry ...；不要把 unless 當 because。", "tip": "用 if ... not 改寫一次，看兩句意思是否相同。", "course": "D Unless 條件句；細項 35。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (263,'{"number": 263, "sentence": "My friend, along with two classmates, are preparing the display.", "mark": "cross", "topic": "現在式主謂一致：近距離陷阱", "wrong": "are preparing", "fix": "is preparing", "correct_sentence": "My friend, along with two classmates, is preparing the display.", "hint": "找真正主語，不要被中間的 of、with、along with 或長修飾語騙到。", "location": "把原句的「are preparing」圈起來，與同一位置應有的「is preparing」比較。不要把沒有錯的部分一併重寫。", "reason": "the number of students 是單數主語 number；the students 是複數；動詞要跟真正主語配合。", "tip": "先遮住主語後面那一長串修飾語。", "course": "G 前置知識與 if 條件句；細項 74。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (264,'{"number": 264, "sentence": "None of the computers was damaged during the storm.", "mark": "tick", "topic": "none of / another / the other", "wrong": "", "fix": "", "correct_sentence": "None of the computers was damaged during the storm.", "hint": "看 none 後有沒有 of；再看 another 後的單數名詞及已經提過的兩件物件。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "none of + 指定的一群人／東西；another + 單數可數名詞表示另外一個；若明確只有兩個，第二個通常叫 the other。", "tip": "背短語：none of the books；another chair；one ... the other。", "course": "C 不定代名詞；細項 40。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (265,'{"number": 265, "sentence": "Unless we leave now, we will miss the school bus.", "mark": "tick", "topic": "unless = if ... not", "wrong": "", "fix": "", "correct_sentence": "Unless we leave now, we will miss the school bus.", "hint": "留意 unless 這個字：它本身已帶「除非／如果不」的意思。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "Unless you hurry, you will miss the train = If you do not hurry ...；不要把 unless 當 because。", "tip": "用 if ... not 改寫一次，看兩句意思是否相同。", "course": "D Unless 條件句；細項 35。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (266,'{"number": 266, "sentence": "No one were injured during the practice drill.", "mark": "cross", "topic": "nobody / no one + 單數動詞", "wrong": "were", "fix": "was", "correct_sentence": "No one was injured during the practice drill.", "hint": "句子主語是 nobody / no one。", "location": "把原句的「were」圈起來，與同一位置應有的「was」比較。不要把沒有錯的部分一併重寫。", "reason": "nobody/no one 雖然表示沒有人，仍用單數動詞：Nobody knows。", "tip": "不要見到「沒有人」就誤用複數動詞。", "course": "C 不定代名詞；細項 28。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (267,'{"number": 267, "sentence": "We can borrow two books at a time.", "mark": "tick", "topic": "can / could 後接動詞原形", "wrong": "", "fix": "", "correct_sentence": "We can borrow two books at a time.", "hint": "找到 can 或 could，看看後面的動詞有沒有多加 to、-s 或 -ing。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "can/could 是情態動詞，後面直接跟原形：can swim，不是 can to swim。", "tip": "把 can、could 與下一個動詞連在一起檢查。", "course": "B 不帶 to 的動詞原形；細項 16。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (268,'{"number": 268, "sentence": "The Earth move around the Sun.", "mark": "cross", "topic": "一般事實及科學真理", "wrong": "move", "fix": "moves", "correct_sentence": "The Earth moves around the Sun.", "hint": "句子在講普遍成立的事實，而不是某個人此刻正在做的事。", "location": "把原句的「move」圈起來，與同一位置應有的「moves」比較。不要把沒有錯的部分一併重寫。", "reason": "科學事實、定義、自然規律常用一般現在式；沒有理由就不要改成現在進行式。", "tip": "先想：「這句話明天也通常成立嗎？」成立就傾向用現在式。", "course": "A 現在式與現在進行式；細項 02。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (269,'{"number": 269, "sentence": "I usually cycle to school, but this week I am taking the bus.", "mark": "tick", "topic": "短期情況與長期習慣", "wrong": "", "fix": "", "correct_sentence": "I usually cycle to school, but this week I am taking the bus.", "hint": "留意 this week、this month、for now 和 usually 的對比。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "平常習慣用現在式；只在這段時間暫時發生的事情常用進行式。", "tip": "把「通常」和「暫時」在心中分開。", "course": "A 現在式與現在進行式；細項 12。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (270,'{"number": 270, "sentence": "He must brings his student card tomorrow.", "mark": "cross", "topic": "must + 動詞原形", "wrong": "must brings", "fix": "must bring", "correct_sentence": "He must bring his student card tomorrow.", "hint": "must 表示強烈的責任、要求或必要。", "location": "把原句的「must brings」圈起來，與同一位置應有的「must bring」比較。不要把沒有錯的部分一併重寫。", "reason": "must + 原形；不接 to，不因主語單數而變 musts。", "tip": "must 的下一個動詞保持原形。", "course": "E Must / have to / need to；細項 41。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (271,'{"number": 271, "sentence": "You needn’t worry about the transport; we have booked a bus.", "mark": "tick", "topic": "needn’t 後直接原形", "wrong": "", "fix": "", "correct_sentence": "You needn’t worry about the transport; we have booked a bus.", "hint": "這是情態用法 needn’t，與 don’t need to 結構不同。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "needn’t + 原形，不加 to；例 needn’t worry。", "tip": "分清 needn’t go 與 don’t need to go。", "course": "E Must / have to / need to；細項 48。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (272,'{"number": 272, "sentence": "We learnt something useful during the workshop.", "mark": "tick", "topic": "形容詞放在 -thing/-one 後", "wrong": "", "fix": "", "correct_sentence": "We learnt something useful during the workshop.", "hint": "檢查 something useful、anyone reliable 這類不定代名詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "修飾不定代名詞的形容詞通常放在後面：something interesting，而不是 interesting something。", "tip": "背一組：anything new、someone kind。", "course": "C 不定代名詞；細項 34。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (273,'{"number": 273, "sentence": "Jayden wants to study at an university overseas.", "mark": "cross", "topic": "冠詞：a / an / the / 零冠詞", "wrong": "an university", "fix": "a university", "correct_sentence": "Jayden wants to study at a university overseas.", "hint": "先問名詞是否第一次出現、是否特定，再聽開首讀音。", "location": "把原句的「an university」圈起來，與同一位置應有的「a university」比較。不要把沒有錯的部分一併重寫。", "reason": "a/an 常用於首次提及的單數可數名詞；the 指已知或特定；某些固定用法不加冠詞。", "tip": "a university（/y/ 音）、an honest answer（h 不發音）、the UK。", "course": "G 前置知識與 if 條件句；細項 75。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (274,'{"number": 274, "sentence": "The teacher spoke slowly so that everyone could follow.", "mark": "tick", "topic": "so that 後有主語與動詞", "wrong": "", "fix": "", "correct_sentence": "The teacher spoke slowly so that everyone could follow.", "hint": "so that 表示「為了讓……」，後面通常有完整的主語和謂語。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "so that + 主語 + 動詞／情態動詞，不等於 so as to + 原形。", "tip": "檢查 so that 後，有沒有「誰做甚麼」。", "course": "F So / so that / so as to；細項 53。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (275,'{"number": 275, "sentence": "Visitors must not feeding the animals at the rescue centre.", "mark": "cross", "topic": "must not / mustn’t = 禁止", "wrong": "must not feeding", "fix": "must not feed", "correct_sentence": "Visitors must not feed the animals at the rescue centre.", "hint": "告示清楚說不准做一件事。", "location": "把原句的「must not feeding」圈起來，與同一位置應有的「must not feed」比較。不要把沒有錯的部分一併重寫。", "reason": "must not 表「不准」，不是「沒有必要」；必要時與 do not have to 作比較。", "tip": "看到 No entry / strictly prohibited，想 must not。", "course": "E Must / have to / need to；細項 42。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (276,'{"number": 276, "sentence": "Our class has raised three thousand dollars so far.", "mark": "tick", "topic": "現在完成式：至今的成果", "wrong": "", "fix": "", "correct_sentence": "Our class has raised three thousand dollars so far.", "hint": "留意 so far、up to now、since 等與現在仍有關係的時間線索。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "have/has + 過去分詞，說明以前發生而與現在有關的結果。", "tip": "「至今」想 have/has done；「昨天」想 did。", "course": "G 前置知識與 if 條件句；細項 63。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (277,'{"number": 277, "sentence": "Everyone is welcome to join the workshop.", "mark": "tick", "topic": "everyone / everybody 用單數動詞", "wrong": "", "fix": "", "correct_sentence": "Everyone is welcome to join the workshop.", "hint": "留意 everyone、everybody 雖然指很多人，文法上當單數。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "everyone/everybody + is/has/動詞-s；不能因為意思是「所有人」而用 are。", "tip": "把 everyone 當作 he/she 來試配動詞。", "course": "C 不定代名詞；細項 26。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (278,'{"number": 278, "sentence": "I would rather stay at home than go shopping.", "mark": "tick", "topic": "would rather + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "I would rather stay at home than go shopping.", "hint": "見到 would rather，就要檢查後面的第一個動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "表示「寧願」時通常用 would rather + 原形，不接 to：rather stay。", "tip": "記 would rather stay than go。", "course": "B 不帶 to 的動詞原形；細項 23。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (279,'{"number": 279, "sentence": "Do we have to wear sports shoes tomorrow?", "mark": "tick", "topic": "have to 問句用 do/does", "wrong": "", "fix": "", "correct_sentence": "Do we have to wear sports shoes tomorrow?", "hint": "句子在問某人是否必須做某事。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "一般現在式問句用 Do/Does + 主語 + have to + 原形；不是 Does she has to。", "tip": "Does he have to go? 一口氣檢查兩個地方。", "course": "E Must / have to / need to；細項 50。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (280,'{"number": 280, "sentence": "Please bring something to write on.", "mark": "tick", "topic": "人用 -one/-body；物用 -thing", "wrong": "", "fix": "", "correct_sentence": "Please bring something to write on.", "hint": "留意動詞的意思：是否在找人，還是在找東西？", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "someone/anyone/nobody 說人；something/anything/nothing 說事物。", "tip": "直接問「要找的是人還是物？」", "course": "C 不定代名詞；細項 33。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (281,'{"number": 281, "sentence": "Someone knows where the keys are kept.", "mark": "tick", "topic": "someone / somebody 單數一致", "wrong": "", "fix": "", "correct_sentence": "Someone knows where the keys are kept.", "hint": "有人，但不知是哪一個人；找 someone/somebody 所配的動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "someone/somebody 在文法上用單數動詞：Someone is waiting。", "tip": "遇到 someone，先想「某一個人」。", "course": "C 不定代名詞；細項 27。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (282,'{"number": 282, "sentence": "Our coach has worked here for 2022.", "mark": "cross", "topic": "for / since 的時間用法", "wrong": "for 2022", "fix": "since 2022", "correct_sentence": "Our coach has worked here since 2022.", "hint": "找出時間是「一段長度」還是「開始那個點」。", "location": "把原句的「for 2022」圈起來，與同一位置應有的「since 2022」比較。不要把沒有錯的部分一併重寫。", "reason": "for + 一段時間（for three years）；since + 起點（since 2023）。", "tip": "for = 多久；since = 從何時開始。", "course": "G 前置知識與 if 條件句；細項 64。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (283,'{"number": 283, "sentence": "He does not know nobody in this new class.", "mark": "cross", "topic": "否定句常用 anything / anybody", "wrong": "nobody", "fix": "anybody", "correct_sentence": "He does not know anybody in this new class.", "hint": "句子前面已有 not 或 never，看看後面用甚麼不定代名詞。", "location": "把原句的「nobody」圈起來，與同一位置應有的「anybody」比較。不要把沒有錯的部分一併重寫。", "reason": "在一般否定句，通常說 do not have anything、did not see anybody；不用雙重否定。", "tip": "前面有 not，後面優先檢查 any- 字頭。", "course": "C 不定代名詞；細項 30。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (284,'{"number": 284, "sentence": "The class collected data so as to improving the survey.", "mark": "cross", "topic": "so as to + 動詞原形", "wrong": "so as to improving", "fix": "so as to improve", "correct_sentence": "The class collected data so as to improve the survey.", "hint": "看 so as to 後面的動詞形式。", "location": "把原句的「so as to improving」圈起來，與同一位置應有的「so as to improve」比較。不要把沒有錯的部分一併重寫。", "reason": "so as to 後直接接原形，表示「為了」：so as to save time。", "tip": "so as to finish，不是 so as to finishing。", "course": "F So / so that / so as to；細項 56。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (285,'{"number": 285, "sentence": "Are the students practising in the music room?", "mark": "tick", "topic": "進行式疑問句與否定句", "wrong": "", "fix": "", "correct_sentence": "Are the students practising in the music room?", "hint": "注意問句的 am/is/are 位置，以及否定句中的 not。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "問句把 be 放主語前：Are they coming?；否定用 is not / are not + -ing。", "tip": "把陳述句 They are waiting 改成問句 Are they waiting? 試一遍。", "course": "A 現在式與現在進行式；細項 11。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (286,'{"number": 286, "sentence": "She does not eat meat at lunchtime.", "mark": "tick", "topic": "現在式否定：do not / does not", "wrong": "", "fix": "", "correct_sentence": "She does not eat meat at lunchtime.", "hint": "找 not 前面的助動詞，留意主語單複數。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "he/she/it 用 does not + 原形；I/you/we/they 用 do not + 原形。", "tip": "把「doesn''t + 原形」當成一組。", "course": "A 現在式與現在進行式；細項 06。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (287,'{"number": 287, "sentence": "If the bus will arrive on time, we will reach school before eight.", "mark": "cross", "topic": "First conditional：真實可能的將來", "wrong": "bus will arrive", "fix": "bus arrives", "correct_sentence": "If the bus arrives on time, we will reach school before eight.", "hint": "if 子句說將來有可能發生的情況，主句有 will。", "location": "把原句的「bus will arrive」圈起來，與同一位置應有的「bus arrives」比較。不要把沒有錯的部分一併重寫。", "reason": "常用 if + 現在式，will + 原形；if 子句一般不直接用 will 表普通未來。", "tip": "If it rains, we will stay inside。", "course": "G 前置知識與 if 條件句；細項 71。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (288,'{"number": 288, "sentence": "If we had left earlier, we would have caught the ferry.", "mark": "tick", "topic": "Third conditional：對過去的假設", "wrong": "", "fix": "", "correct_sentence": "If we had left earlier, we would have caught the ferry.", "hint": "句子是在想「如果當時……就好了」，但事情已不可能改變。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "常用 if + had + 過去分詞，would have + 過去分詞。", "tip": "過去沒有發生的事：If I had studied, I would have passed。", "course": "G 前置知識與 if 條件句；細項 73。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (289,'{"number": 289, "sentence": "She saves her notes online so that she can opens them anywhere.", "mark": "cross", "topic": "so that + can：現在目的", "wrong": "can opens", "fix": "can open", "correct_sentence": "She saves her notes online so that she can open them anywhere.", "hint": "句子在說現在／將來的目的，目標是「能夠做到」。", "location": "把原句的「can opens」圈起來，與同一位置應有的「can open」比較。不要把沒有錯的部分一併重寫。", "reason": "用 so that + 人 + can + 原形：I speak clearly so that you can hear。", "tip": "目的句中 can 後不可加 to。", "course": "F So / so that / so as to；細項 54。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (290,'{"number": 290, "sentence": "I have lived in this district for six years.", "mark": "tick", "topic": "for / since 的時間用法", "wrong": "", "fix": "", "correct_sentence": "I have lived in this district for six years.", "hint": "找出時間是「一段長度」還是「開始那個點」。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "for + 一段時間（for three years）；since + 起點（since 2023）。", "tip": "for = 多久；since = 從何時開始。", "course": "G 前置知識與 if 條件句；細項 64。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (291,'{"number": 291, "sentence": "Mr Lee goes to the gym on Saturdays.", "mark": "tick", "topic": "第三身 -es 與 -ies 拼字", "wrong": "", "fix": "", "correct_sentence": "Mr Lee goes to the gym on Saturdays.", "hint": "主語是單數；注意動詞結尾 ch、sh、o 或 consonant + y。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "watch → watches；study → studies。不是任何動詞都只直接加 -s。", "tip": "先看字尾，再決定加 -s、-es 或改 y 為 ies。", "course": "A 現在式與現在進行式；細項 04。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (292,'{"number": 292, "sentence": "The teacher watchs the class carefully.", "mark": "cross", "topic": "第三身 -es 與 -ies 拼字", "wrong": "watchs", "fix": "watches", "correct_sentence": "The teacher watches the class carefully.", "hint": "主語是單數；注意動詞結尾 ch、sh、o 或 consonant + y。", "location": "把原句的「watchs」圈起來，與同一位置應有的「watches」比較。不要把沒有錯的部分一併重寫。", "reason": "watch → watches；study → studies。不是任何動詞都只直接加 -s。", "tip": "先看字尾，再決定加 -s、-es 或改 y 為 ies。", "course": "A 現在式與現在進行式；細項 04。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (293,'{"number": 293, "sentence": "I did not see anybody outside the sports hall.", "mark": "tick", "topic": "否定句常用 anything / anybody", "wrong": "", "fix": "", "correct_sentence": "I did not see anybody outside the sports hall.", "hint": "句子前面已有 not 或 never，看看後面用甚麼不定代名詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "在一般否定句，通常說 do not have anything、did not see anybody；不用雙重否定。", "tip": "前面有 not，後面優先檢查 any- 字頭。", "course": "C 不定代名詞；細項 30。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (294,'{"number": 294, "sentence": "The weather getting warmer as spring approaches.", "mark": "cross", "topic": "正在改變的情況及趨勢", "wrong": "getting", "fix": "is getting", "correct_sentence": "The weather is getting warmer as spring approaches.", "hint": "留意 gradually、these days、more and more 等表示變化中的字。", "location": "把原句的「getting」圈起來，與同一位置應有的「is getting」比較。不要把沒有錯的部分一併重寫。", "reason": "強調現正發展的趨勢時，通常用現在進行式；它不同於永遠不變的事實。", "tip": "想像有一條上升／下降中的線：is increasing。", "course": "A 現在式與現在進行式；細項 13。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (295,'{"number": 295, "sentence": "I moved aside so that to the visitors could see the display.", "mark": "cross", "topic": "so that 後有主語與動詞", "wrong": "so that to the visitors", "fix": "so that the visitors", "correct_sentence": "I moved aside so that the visitors could see the display.", "hint": "so that 表示「為了讓……」，後面通常有完整的主語和謂語。", "location": "把原句的「so that to the visitors」圈起來，與同一位置應有的「so that the visitors」比較。不要把沒有錯的部分一併重寫。", "reason": "so that + 主語 + 動詞／情態動詞，不等於 so as to + 原形。", "tip": "檢查 so that 後，有沒有「誰做甚麼」。", "course": "F So / so that / so as to；細項 53。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (296,'{"number": 296, "sentence": "The pupils were made to tidy the classroom.", "mark": "tick", "topic": "被動 be made + to + 動詞", "wrong": "", "fix": "", "correct_sentence": "The pupils were made to tidy the classroom.", "hint": "同樣是 make，但看誰是主語：是「被迫做」嗎？", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "主動 made us clean 不加 to；變被動時要加 to：We were made to clean。", "tip": "主動不加 to；被動 be made to do。", "course": "B 不帶 to 的動詞原形；細項 25。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (297,'{"number": 297, "sentence": "The workers were made wear safety helmets.", "mark": "cross", "topic": "被動 be made + to + 動詞", "wrong": "made wear", "fix": "made to wear", "correct_sentence": "The workers were made to wear safety helmets.", "hint": "同樣是 make，但看誰是主語：是「被迫做」嗎？", "location": "把原句的「made wear」圈起來，與同一位置應有的「made to wear」比較。不要把沒有錯的部分一併重寫。", "reason": "主動 made us clean 不加 to；變被動時要加 to：We were made to clean。", "tip": "主動不加 to；被動 be made to do。", "course": "B 不帶 to 的動詞原形；細項 25。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (298,'{"number": 298, "sentence": "You must keep the laboratory door closed.", "mark": "tick", "topic": "must 後接動詞原形", "wrong": "", "fix": "", "correct_sentence": "You must keep the laboratory door closed.", "hint": "找到 must，再看緊接的動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "must 後必須用動詞原形，不能接 to 或過去式；例如 must finish。", "tip": "must 後面的動詞不要加 -s、-ed 或 to。", "course": "B 不帶 to 的動詞原形；細項 17。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (299,'{"number": 299, "sentence": "Our coach reminds always us to warm up.", "mark": "cross", "topic": "現在式的 always / never / sometimes", "wrong": "reminds always", "fix": "always reminds", "correct_sentence": "Our coach always reminds us to warm up.", "hint": "留意 always、never、sometimes 放在主要動詞附近。", "location": "把原句的「reminds always」圈起來，與同一位置應有的「always reminds」比較。不要把沒有錯的部分一併重寫。", "reason": "頻率副詞通常放在一般動詞前、be 動詞後；「never」本身已表示否定。", "tip": "問自己：是否把 never 再配 not，變成雙重否定？", "course": "A 現在式與現在進行式；細項 07。"}'::jsonb);
insert into public.error_identifier_jayden_key(number,data) values (300,'{"number": 300, "sentence": "Please let me explain the rules again.", "mark": "tick", "topic": "let + 人 + 動詞原形", "wrong": "", "fix": "", "correct_sentence": "Please let me explain the rules again.", "hint": "找到 let，特別留意 let us / let me / let him 後面的動詞。", "location": "這題的關鍵結構已經正確。就算你覺得可以換另一種說法，也不代表原句有文法錯誤；此處選 ✓。", "reason": "let someone do something，後面通常不用 to；例如 let me try。", "tip": "let + 人 + 原形，三件事排在一起。", "course": "B 不帶 to 的動詞原形；細項 20。"}'::jsonb);
